INSERT INTO classes (id, code, name, role, description, xp_rate, base_hp, base_atk, base_def, base_mag, base_magic_def, base_spd, base_evasion, base_crit_chance, base_crit_damage, base_mana, created_at, lore) VALUES
  (1, 'GUERRERO', 'Guerrero', 'Tanque', 'Clase base enfocada en defensa y cuerpo a cuerpo.', 1.00, 65, 14, 16, 7, 8, 9, 10.00, 10.00, 10.00, 60, '2026-07-15T05:03:00.823Z', NULL),
  (2, 'MAGO', 'Mago', 'Daño mágico', 'Clase base con alto MAG y daño elemental.', 1.20, 50, 8, 8, 18, 12, 8, 10.00, 10.00, 10.00, 100, '2026-07-15T05:03:00.823Z', NULL),
  (3, 'ARQUERO', 'Arquero', 'Ataque a distancia', 'Clase base con daño físico y alta precisión.', 1.00, 55, 13, 10, 8, 7, 12, 10.00, 10.00, 10.00, 70, '2026-07-15T05:03:00.823Z', NULL),
  (4, 'PICARO', 'Pícaro', 'Crítico/velocidad', 'Clase base veloz con alto crítico y evasión.', 1.00, 50, 13, 9, 7, 7, 15, 10.00, 10.00, 10.00, 70, '2026-07-15T05:03:00.823Z', NULL),
  (5, 'SACERDOTE', 'Sacerdote', 'Soporte/curación', 'Clase base de curación y apoyo con buena defensa mágica.', 1.10, 55, 7, 12, 12, 20, 8, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', NULL),
  (6, 'MONJE', 'Monje', 'Golpe/defensa', 'Rama Guerrero orientada al puño y control.', 1.00, 81, 18, 21, 9, 10, 11, 10.00, 10.00, 10.00, 75, '2026-07-15T05:03:00.823Z', 'Renunció al acero el día en que descubrió que sus propios puños, templados por años de disciplina, golpeaban con más certeza que cualquier arma forjada. — Ataque y defensa física'),
  (7, 'ESPADACHIN', 'Espadachín', 'Espada', 'Rama Guerrero de daño de espada y técnicas rápidas.', 1.00, 81, 18, 20, 9, 10, 11, 10.00, 10.00, 10.00, 75, '2026-07-15T05:03:00.823Z', 'Encontró una espada mágica que responde a su voluntad como una extensión de su propio brazo; cada corte suyo es pura velocidad hecha acero. — Ataque físico'),
  (8, 'CABALLERO', 'Caballero', 'Defensa pura', 'Rama Guerrero de alta defensa y aguante.', 1.00, 81, 18, 21, 9, 10, 11, 10.00, 10.00, 10.00, 75, '2026-07-15T05:03:00.823Z', 'Se cubrió con una armadura pesada hasta volverse un muro viviente: donde otros retroceden, él avanza, porque nada que lo golpee puede quebrar su voluntad de proteger. — Defensa física'),
  (9, 'BERSERKER', 'Berserker', 'Daño bruto', 'Rama Guerrero con alto daño y crítico.', 1.00, 81, 18, 20, 9, 10, 11, 10.00, 10.00, 10.00, 75, '2026-07-15T05:03:00.823Z', 'Dejó que la furia del combate lo consumiera por completo, y en ese abandono encontró un poder que ningún guerrero contenido podría igualar. — Ataque físico'),
  (10, 'GUERRERO_MAGUS', 'Guerrero Magus', 'Mago guerrero', 'Rama Guerrero que mezcla daño físico y magia.', 1.05, 81, 18, 20, 9, 10, 11, 10.00, 10.00, 10.00, 75, '2026-07-15T05:03:00.823Z', 'Aprendió a canalizar magia elemental a través de su propio acero, demostrando que la fuerza bruta y el arcano no tienen por qué ser caminos separados. — Ataque físico y mágico'),
  (12, 'NIGROMANTE', 'Nigromante', 'Oscuridad', 'Rama Mago con maldiciones y daño oscuro.', 1.20, 63, 10, 10, 20, 20, 10, 10.00, 10.00, 10.00, 125, '2026-07-15T05:03:00.823Z', 'Aprendió a susurrarle órdenes a la muerte misma, y ahora los caídos se levantan para pelear a su lado sin hacer preguntas. — Ataque mágico (oscuro)'),
  (13, 'INVOCADOR', 'Invocador', 'Aliados', 'Rama Mago basada en invocaciones y apoyo.', 1.20, 63, 10, 10, 20, 20, 10, 10.00, 10.00, 10.00, 125, '2026-07-15T05:03:00.823Z', 'Dejó de pelear con sus propias manos el día en que descubrió que podía convocar aliados desde otros planos para que lucharan por él. — Soporte mágico (invocación)'),
  (14, 'ELEMENTAL', 'Elemental', 'Daño elemental', 'Rama Mago con daño elemental múltiple.', 1.20, 63, 10, 10, 20, 20, 10, 10.00, 10.00, 10.00, 125, '2026-07-15T05:03:00.823Z', 'Rompió las cadenas de un solo hechizo y aprendió a doblegar varios elementos a la vez, convirtiendo cada combate en una tormenta impredecible. — Ataque mágico'),
  (15, 'MAGO_DIVINO', 'Mago Divino', 'Poder supremo', 'Rama Mago con magia y daño elevado.', 1.20, 63, 10, 10, 20, 20, 10, 10.00, 10.00, 10.00, 125, '2026-07-15T05:03:00.823Z', 'Sintió el llamado de un poder superior y fusionó su magia con la luz divina, elevando cada hechizo a algo casi sagrado. — Ataque mágico'),
  (16, 'CAZADOR', 'Cazador', 'Precisión', 'Rama Arquero de daño estable y tiros precisos.', 1.00, 69, 17, 13, 10, 9, 15, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Pasó tanto tiempo rastreando presas que sus flechas ya no fallan; cada disparo suyo es la conclusión de una cacería que empezó mucho antes del combate. — Ataque físico'),
  (17, 'FRANCOTIRADOR', 'Francotirador', 'Penetración', 'Rama Arquero que ignora armadura enemiga.', 1.00, 69, 17, 13, 10, 9, 15, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Aprendió a encontrar la grieta exacta en cualquier armadura, disparando con una precisión que ignora hasta la mejor defensa. — Ataque físico'),
  (18, 'RANGER', 'Ranger', 'Versatilidad', 'Rama Arquero que combina daño y apoyo.', 1.00, 69, 17, 13, 10, 9, 15, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Encontró el equilibrio entre el arco y la magia de la naturaleza, volviéndose tan útil protegiendo a sus aliados como derribando enemigos. — Ataque físico y mágico'),
  (19, 'ASESINO_ARCANO', 'Arquero Umbrío', 'Mágico/crítico', 'Rama Arquero con magia oscura y críticos.', 1.00, 69, 16, 13, 10, 9, 15, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Impregnó sus flechas con magia oscura, y ahora cada disparo certero es también un golpe directo a la mente del enemigo. — Ataque físico y mágico'),
  (20, 'ELFO_SILVESTRE', 'Elfo Silvestre', 'Bosque', 'Rama Arquero con daño natural y apoyo.', 1.00, 69, 16, 13, 10, 9, 15, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'El bosque mismo parece guiar sus flechas, un arquero que pelea en armonía con la naturaleza que lo rodea. — Ataque físico y mágico'),
  (21, 'NINJA', 'Ninja', 'Velocidad', 'Rama Pícaro con golpes rápidos y evasión.', 1.00, 63, 16, 11, 9, 9, 20, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Aprendió técnicas que ni el mejor espadachín podría replicar, golpeando y desapareciendo antes de que el enemigo procese lo que pasó. — Ataque físico'),
  (22, 'ASESINO', 'Asesino', 'Letal', 'Rama Pícaro especializada en críticos letales.', 1.00, 63, 17, 11, 9, 9, 19, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Perfeccionó el arte del golpe letal hasta convertirlo en su única filosofía: un combate, un golpe, un final. — Ataque físico (crítico)'),
  (23, 'LADRON_MAESTRO', 'Ladrón Maestro', 'Robo', 'Rama Pícaro enfocada en saqueo y velocidad.', 1.00, 63, 16, 11, 9, 9, 20, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Ya no roba por necesidad, roba porque es el mejor haciéndolo; ningún bolsillo ni cofre está a salvo de sus manos. — Ataque físico (utilidad)'),
  (24, 'ENVENENADOR', 'Envenenador', 'Veneno', 'Rama Pícaro con daño por estados y debuffs.', 1.00, 63, 16, 11, 9, 9, 20, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Descubrió que la paciencia mata tan bien como el acero, dejando que sus venenos hagan el trabajo mientras él observa desde la distancia. — Ataque físico (veneno)'),
  (25, 'ESPECIALISTA_TRAMPAS', 'Especialista en Trampas', 'Control', 'Rama Pícaro centrada en trampas y control.', 1.00, 63, 16, 11, 9, 9, 19, 10.00, 10.00, 10.00, 88, '2026-07-15T05:03:00.823Z', 'Convirtió el campo de batalla mismo en su arma, sembrando trampas que deciden el combate antes de que el primer golpe siquiera se dé. — Ataque físico (control)'),
  (26, 'CLERIGO', 'Clérigo', 'Curación', 'Rama Sacerdote con curaciones y escudos fuertes.', 1.10, 69, 9, 15, 20, 20, 10, 10.00, 10.00, 10.00, 113, '2026-07-15T05:03:00.823Z', 'Perfeccionó el arte de curar hasta volverlo casi instantáneo, levantando escudos de fe que protegen a todo su equipo. — Curación / soporte mágico'),
  (27, 'DRUIDA', 'Druida', 'Naturaleza', 'Rama Sacerdote con magia natural y apoyo.', 1.10, 69, 9, 15, 20, 20, 10, 10.00, 10.00, 10.00, 113, '2026-07-15T05:03:00.823Z', 'Aprendió a hablar el idioma silencioso de la naturaleza, y ahora la usa tanto para sanar a sus aliados como para castigar a sus enemigos. — Ataque y soporte mágico'),
  (28, 'TEMPLARIO', 'Templario', 'Defensa mágica', 'Rama Sacerdote con escudos y aguante.', 1.10, 69, 9, 15, 19, 21, 10, 10.00, 10.00, 10.00, 113, '2026-07-15T05:03:00.823Z', 'Cambió las curaciones simples por escudos capaces de resistir cualquier golpe, un muro de fe tan duro como cualquier armadura. — Defensa mágica'),
  (29, 'SANADOR_DIVINO', 'Sanador Divino', 'Curación suprema', 'Rama Sacerdote con curas masivas.', 1.10, 69, 9, 15, 20, 20, 10, 10.00, 10.00, 10.00, 113, '2026-07-15T05:03:00.823Z', 'Sus curaciones dejaron de ser un alivio para convertirse en milagros; ha traído de vuelta a compañeros que todos daban por perdidos. — Curación suprema'),
  (30, 'INQUISIDOR', 'Inquisidor', 'Anti-magia', 'Rama Sacerdote centrada en purificación.', 1.10, 69, 9, 15, 19, 21, 10, 10.00, 10.00, 10.00, 113, '2026-07-15T05:03:00.823Z', 'Dedicó su fe a purgar la oscuridad allá donde la encuentre, castigando a las criaturas malignas con la misma devoción con la que cura a los suyos. — Ataque mágico (purificación)'),
  (31, 'MAGO_PIROMANTICO', 'Mago Piromántico', 'Especialista Fuego', 'Rama Mago especializada en el elemento Fuego.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Eligió el fuego por sobre todos los elementos, y ahora cada hechizo suyo arde con una intensidad que ni él mismo puede contener del todo. — Ataque mágico (Fuego)'),
  (32, 'MAGO_CRIOMANTICO', 'Mago Criomántico', 'Especialista Hielo', 'Rama Mago especializada en el elemento Hielo.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Aprendió a congelar el tiempo mismo de sus enemigos, un instante a la vez, con hechizos tan fríos como su concentración. — Ataque mágico (Hielo)'),
  (33, 'MAGO_ELECTROMANTICO', 'Mago Electromántico', 'Especialista Rayo', 'Rama Mago especializada en el elemento Rayo.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Domesticó al rayo hasta volverlo una extensión de su propia voluntad, golpeando antes de que el trueno siquiera se escuche. — Ataque mágico (Rayo)'),
  (34, 'MAGO_HIDROMANTE', 'Mago Hidromante', 'Especialista Agua', 'Rama Mago especializada en el elemento Agua.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Encontró en el agua una fuerza tan flexible como implacable, capaz de erosionar cualquier defensa con paciencia infinita. — Ataque mágico (Agua)'),
  (35, 'MAGO_GEOMANTICO', 'Mago Geomántico', 'Especialista Tierra', 'Rama Mago especializada en el elemento Tierra.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Aprendió a escuchar a la tierra bajo sus pies, y ahora la hace responder a su llamado con la fuerza de montañas enteras. — Ataque mágico (Tierra)'),
  (36, 'MAGO_AEROMANTE', 'Mago Aeromante', 'Especialista Viento', 'Rama Mago especializada en el elemento Viento.', 1.20, 76, 12, 12, 24, 24, 13, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Se volvió tan veloz como el viento que domina, golpeando y desapareciendo antes de que el enemigo pueda reaccionar. — Ataque mágico (Viento)'),
  (37, 'MAGO_LUMINOSO', 'Mago Luminoso', 'Especialista Luz', 'Rama Mago especializada en el elemento Luz.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Canalizó la luz misma como arma, iluminando el campo de batalla con hechizos que queman tanto como purifican. — Ataque mágico (Luz)'),
  (38, 'MAESTRO_MONJE', 'Maestro Monje', 'Puño maestro', 'Monje que perfecciona el combate sin armas.', 1.00, 97, 22, 27, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Sus puños ya no son solo músculo y hueso: son la culminación de una vida entera dedicada a perfeccionar el combate sin armas. — Ataque y defensa física'),
  (39, 'MONJE_OSCURO', 'Monje Oscuro', 'Puño oscuro', 'Monje corrompido por magia oscura.', 1.00, 97, 23, 25, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'La oscuridad se filtró en su disciplina hasta fusionarse con ella; cada golpe suyo lleva un eco de la corrupción que aceptó voluntariamente. — Ataque y defensa física'),
  (40, 'MONJE_SISMICO', 'Monje Sísmico', 'Puño tierra', 'Monje que canaliza el poder de la tierra.', 1.00, 97, 23, 25, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Aprendió a golpear no solo con el cuerpo sino con la tierra misma bajo sus pies, haciendo temblar el suelo con cada impacto. — Ataque y defensa física'),
  (41, 'MONJE_DIVINO', 'Monje Divino', 'Puño divino', 'Monje que canaliza energía divina en sus golpes.', 1.00, 97, 22, 25, 12, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Sus puños fueron bendecidos por una fuerza superior; cada golpe que asesta es tanto un acto de fe como de combate. — Ataque físico y defensa mágica'),
  (42, 'MAESTRO_MONJE_SUPREMO', 'Maestro Monje Supremo', 'Puño supremo', 'El pináculo del combate sin armas.', 1.00, 119, 27, 36, 14, 15, 16, 10.00, 10.00, 10.00, 111, '2026-07-15T05:03:00.823Z', 'Alcanzó el límite absoluto del combate sin armas: ya no pelea, se ha convertido en la pelea misma. — Ataque y defensa física'),
  (43, 'MAESTRO_ESPADACHIN', 'Maestro Espadachín', 'Espada maestra', 'Domina las técnicas de corte avanzadas.', 1.00, 97, 23, 24, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Sus técnicas de corte ya no se distinguen del instinto; la espada y su brazo se mueven como un solo pensamiento. — Ataque físico'),
  (44, 'CABALLERO_OSCURO', 'Caballero Oscuro', 'Espada oscura', 'Espadachín corrompido por magia oscura.', 1.00, 97, 23, 24, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Cambió el brillo de su armadura por las sombras, aceptando un poder corrupto a cambio de una fuerza que la luz jamás podría ofrecerle. — Ataque y defensa física'),
  (45, 'PALADIN', 'Paladín', 'Defensa sagrada', 'Caballero que canaliza magia divina.', 1.00, 97, 22, 27, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Su armadura ahora resplandece con magia divina: ya no solo protege con acero, protege con fe. — Defensa física y mágica'),
  (46, 'CABALLERO_SAGRADO', 'Paladín Celestial', 'Defensa celestial', 'Paladín bendecido con armadura celestial.', 1.00, 119, 27, 36, 14, 15, 16, 10.00, 10.00, 10.00, 111, '2026-07-15T05:03:00.823Z', 'Fue bendecido con una armadura celestial que lo vuelve casi imposible de derribar, un bastión viviente entre el mal y los inocentes. — Defensa física y mágica'),
  (47, 'PALADIN_OSCURO', 'Caballero Abisal', 'Defensa corrupta', 'Paladín que cayó en la oscuridad.', 1.00, 97, 22, 27, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Cayó en la oscuridad sin perder su armadura sagrada, y ahora protege con la misma devoción con la que antaño servía a la luz. — Defensa física y mágica'),
  (48, 'CABALLERO_BLINDADO', 'Caballero Blindado', 'Defensa de titán', 'Caballero con armadura indestructible.', 1.00, 97, 22, 27, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Forjó una armadura tan indestructible que ya nadie recuerda haberlo visto sangrar en combate. — Defensa física'),
  (49, 'DRAGON_CABALLERO', 'Paladín Dracónito', 'Sangre de dragón', 'Caballero que porta escamas de dragón.', 1.00, 129, 27, 33, 14, 15, 16, 10.00, 10.00, 10.00, 111, '2026-07-15T05:03:00.823Z', 'Se cubrió con escamas de dragón auténticas, y desde entonces su armadura respira con un poder que no es del todo humano. — Defensa física'),
  (50, 'TITAN_FURIOSO', 'Titán Furioso', 'Furia bruta', 'Berserker que bebió del cáliz de la furia.', 1.00, 97, 23, 24, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Bebió del cáliz de la furia sin mirar atrás, y ahora su ira es tan vasta que apenas cabe en un solo cuerpo. — Ataque físico'),
  (51, 'BERSERKER_DEL_CAOS', 'Titán del Caos', 'Furia oscura', 'Berserker corrompido por el caos.', 1.00, 97, 23, 24, 11, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'El caos se apoderó de su furia hasta corromperla por completo; ya no lucha por rabia, lucha porque el caos mismo lo exige. — Ataque físico'),
  (52, 'MAGO_ESPADA', 'Mago Espada', 'Espada arcana', 'Guerrero Magus que combina espada y magia.', 1.05, 97, 22, 24, 12, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Fusionó el filo de su espada con el arcano hasta que ya no sabe distinguir dónde termina el acero y empieza la magia. — Ataque físico y mágico'),
  (53, 'ARQUEOLOGO_MAGICO', 'Espadachín Arcano', 'Saber ancestral', 'Guerrero Magus experto en ruinas antiguas.', 1.05, 97, 22, 24, 12, 12, 13, 10.00, 10.00, 10.00, 90, '2026-07-15T05:03:00.823Z', 'Cambió el campo de batalla por ruinas olvidadas, y encontró en el saber ancestral un poder que ningún hechizo moderno podría replicar. — Ataque físico y mágico'),
  (54, 'REY_NIGROMANTE', 'Rey Nigromante', 'Oscuridad suprema', 'Nigromante que domina ejércitos de no-muertos.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Ya no invoca no-muertos sueltos: comanda ejércitos enteros de ellos, un monarca que gobierna sobre la muerte misma. — Ataque mágico (oscuro)'),
  (55, 'LICH', 'Lich', 'Inmortalidad arcana', 'Nigromante que trascendió la muerte.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Cruzó el umbral que ningún hechicero se atreve a cruzar y trascendió la muerte por completo, volviéndose inmortal a costa de su propia humanidad. — Ataque mágico (oscuro)'),
  (56, 'INVOCADOR_DEMONIACO', 'Invocador Demoníaco', 'Pactos oscuros', 'Invocador que pacta con demonios.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Firmó pactos con entidades que otros ni se atreven a nombrar, y ahora demonios enteros responden a su llamado. — Soporte mágico (invocación oscura)'),
  (57, 'INVOCADOR_CELESTIAL', 'Invocador Celestial', 'Aliados divinos', 'Invocador que llama a seres celestiales.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Purificó su magia hasta que solo seres celestiales responden a su llamado, guerreros de luz que pelean por una causa justa. — Soporte mágico (invocación divina)'),
  (58, 'INVOCADOR_SALVAJE', 'Invocador Salvaje', 'Bestias salvajes', 'Invocador que doma criaturas salvajes.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Aprendió el lenguaje de las bestias más feroces del mundo y ahora las llama a la batalla como si fueran viejas amigas. — Soporte mágico (invocación salvaje)'),
  (59, 'MAESTRO_ELEMENTAL', 'Maestro Elemental', 'Dominio total', 'Elemental que domina los 8 elementos.', 1.20, 93, 15, 15, 35, 30, 15, 10.00, 10.00, 10.00, 185, '2026-07-15T05:03:00.823Z', 'Dejó de especializarse en un solo elemento para dominarlos todos, convirtiéndose en una fuerza de la naturaleza en sí mismo. — Ataque mágico (multi-elemental)'),
  (60, 'MAGO_COSMICO', 'Mago Cósmico', 'Poder cósmico', 'Mago ultra raro que domina el elemento Cósmico.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Alcanzó un poder tan raro y absoluto que solo un puñado de seres en toda la historia lograron dominar el elemento Cósmico como él. — Ataque mágico (Cósmico)'),
  (61, 'MAGO_ESTELAR', 'Mago Estelar', 'Poder estelar', 'El mago más poderoso jamás visto, casi un mito.', 1.20, 76, 12, 12, 26, 24, 12, 10.00, 10.00, 10.00, 150, '2026-07-15T05:03:00.823Z', 'Su poder trascendió tanto lo divino que algunos dudan si sigue siendo mortal; los que lo vieron pelear lo describen como casi un mito viviente. — Ataque mágico'),
  (62, 'FRANCOTIRADOR_FANTASMAL', 'Francotirador Fantasmal', 'Sigilo letal', 'Francotirador que ataca desde las sombras.', 1.00, 83, 20, 16, 12, 11, 19, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Aprendió a disparar desde las sombras mismas, un fantasma que el enemigo nunca ve llegar hasta que ya es demasiado tarde. — Ataque físico (sigilo)'),
  (63, 'TIRADOR_EXPLOSIVO', 'Tirador Explosivo', 'Flechas explosivas', 'Arquero especializado en flechas explosivas.', 1.00, 83, 22, 16, 12, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Cambió la precisión silenciosa por el estruendo: cada una de sus flechas explota con una fuerza que borra a varios enemigos a la vez. — Ataque físico'),
  (64, 'TIRADOR_VENENO', 'Tirador de Veneno', 'Flechas venenosas', 'Arquero especializado en flechas venenosas.', 1.00, 83, 22, 16, 12, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Sus flechas no necesitan matar al instante; el veneno que llevan hace el resto del trabajo mientras él ya apunta al siguiente blanco. — Ataque físico (veneno)'),
  (66, 'ARQUERO_CELESTIAL', 'Arquero Celestial', 'Flechas de luz', 'Arquero que canaliza magia divina en sus flechas.', 1.00, 83, 19, 16, 13, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Sus flechas ahora arden con magia divina, un castigo de luz para quienes se atreven a enfrentarlo. — Ataque físico y mágico (Luz)'),
  (67, 'BALLESTERO', 'Ballestero', 'Disparo pesado', 'Arquero que cambia el arco por una ballesta pesada.', 1.00, 83, 22, 16, 12, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Cambió la agilidad del arco por el peso brutal de una ballesta, prefiriendo un solo disparo devastador a diez certeros. — Ataque físico'),
  (68, 'ARQUERO_DEL_RAYO', 'Arquero del Rayo', 'Flechas de rayo', 'Arquero especializado en el elemento Rayo.', 1.00, 83, 20, 16, 13, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Cada flecha suya viaja acompañada de un relámpago, golpeando con una velocidad que el ojo apenas alcanza a seguir. — Ataque físico (Rayo)'),
  (69, 'MAESTRO_CAZADOR', 'Maestro Cazador', 'Caza suprema', 'Cazador con cientos de presas a su nombre.', 1.00, 83, 22, 16, 12, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Ya perdió la cuenta de sus presas hace mucho tiempo; su nombre solo se pronuncia con respeto entre quienes sobrevivieron para contarlo. — Ataque físico'),
  (70, 'ELFO_ANTIGUO', 'Elfo Antiguo', 'Sabiduría élfica', 'Elfo Silvestre que porta un arco legendario.', 1.00, 83, 19, 16, 13, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Porta un arco legendario heredado de generaciones élficas pasadas, cargado con toda la sabiduría de su pueblo. — Ataque físico y mágico'),
  (71, 'RANGER_PRIMORDIAL', 'Ranger Primordial', 'Naturaleza pura', 'Ranger que domina la magia primordial del bosque.', 1.00, 83, 20, 16, 13, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Se adentró tanto en la magia primordial del bosque que ya no sabe distinguir dónde termina su voluntad y empieza la de la naturaleza misma. — Ataque físico y mágico'),
  (72, 'GUARDIAN_SILVESTRE', 'Guardián Silvestre', 'Protector natural', 'Ranger dedicado a proteger a sus aliados.', 1.00, 83, 20, 17, 12, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Dejó de cazar para proteger; ahora usa la fuerza del bosque para escudar a sus aliados antes que para derribar enemigos. — Soporte físico y mágico'),
  (73, 'MAESTRO_ASESINO_OSCURO', 'Asesino Umbrío', 'Sombra arcana', 'Asesino Arcano consumido por la oscuridad.', 1.00, 83, 19, 16, 13, 11, 18, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'La oscuridad terminó por consumirlo entero; ya no dispara para ganar, dispara porque las sombras se lo exigen. — Ataque físico y mágico (oscuro)'),
  (74, 'ELFO_SENOR_BOSQUE', 'Elfo Señor del Bosque', 'Corona ancestral', 'El gobernante élfico del bosque ancestral.', 1.00, 102, 23, 20, 17, 14, 22, 10.00, 10.00, 10.00, 130, '2026-07-15T05:03:00.823Z', 'Se convirtió en el gobernante indiscutido del bosque ancestral, una corona que solo el más sabio de los elfos puede portar. — Ataque físico y mágico'),
  (75, 'MAESTRO_ASESINO', 'Maestro Asesino', 'Golpe perfecto', 'Asesino que perfeccionó el golpe letal.', 1.00, 76, 22, 13, 11, 11, 23, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'El golpe letal dejó de ser una técnica para convertirse en su firma; cada enemigo que enfrenta sabe que solo tiene una oportunidad de sobrevivir. — Ataque físico (crítico)'),
  (76, 'ASESINO_DE_ELITE', 'Asesino de Élite', 'Cazador de jefes', 'El asesino más letal, cazador de jefes finales.', 1.00, 76, 22, 13, 11, 11, 23, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Se especializó en cazar a los más peligrosos: jefes que otros temen enfrentar son, para él, simplemente el siguiente contrato. — Ataque físico (crítico)'),
  (77, 'MAESTRO_ENVENENADOR', 'Maestro Envenenador', 'Toxinas supremas', 'Envenenador que domina cinco venenos distintos.', 1.00, 76, 19, 13, 11, 11, 26, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Domina cinco venenos distintos con una precisión casi artística; cada uno diseñado para un tipo distinto de sufrimiento. — Ataque físico (veneno)'),
  (78, 'NINJA_MAESTRO', 'Ninja Maestro', 'Sombra perfecta', 'Ninja que ataca sin ser visto jamás.', 1.00, 76, 19, 13, 11, 11, 26, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Nadie lo ha visto atacar jamás; solo ven las consecuencias, porque ya se ha ido antes de que el golpe registre. — Ataque físico (sigilo)'),
  (79, 'NINJA_SOMBRA', 'Ninja Sombra', 'Técnica oscura', 'Ninja que fusiona sigilo con magia oscura.', 1.00, 76, 20, 13, 11, 11, 25, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Fusionó sus técnicas ninja con magia oscura, volviéndose una amenaza que ataca tanto desde el sigilo como desde las sombras mismas. — Ataque físico y mágico (oscuro)'),
  (80, 'LADRON_LEGENDARIO', 'Ladrón Legendario', 'Saqueo legendario', 'Ladrón Maestro con un historial de robos legendario.', 1.00, 76, 19, 13, 11, 11, 26, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Su historial de robos ya es leyenda en cada rincón del reino; hasta sus víctimas hablan de él con una mezcla de rabia y admiración. — Ataque físico (utilidad)'),
  (81, 'SAQUEADOR_DE_TESOROS', 'Saqueador de Tesoros', 'Cazatesoros', 'Ladrón Maestro experto en encontrar tesoros únicos.', 1.00, 76, 19, 13, 11, 11, 26, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Cambió el saqueo común por la caza de reliquias únicas, encontrando en las ruinas más olvidadas tesoros que nadie más podría hallar. — Ataque físico (utilidad)'),
  (82, 'MERCENARIO', 'Cazador de Reliquias', 'Combate a sueldo', 'Pícaro que se especializa en misiones de combate.', 1.00, 76, 22, 13, 11, 11, 23, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Tras dominar el control absoluto del campo de batalla, decidió que sus habilidades valían demasiado para desperdiciarlas gratis: ahora pelea por quien pague mejor. — Ataque físico'),
  (83, 'EXPLORADOR_MAZMORRAS', 'Explorador de Mazmorras', 'Explorador experto', 'Pícaro experto en explorar mazmorras peligrosas.', 1.00, 76, 19, 13, 11, 11, 24, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Ninguna mazmorra, por peligrosa que sea, lo intimida; conoce sus trucos, sus trampas y sus secretos mejor que quienes las construyeron. — Ataque físico (utilidad)'),
  (84, 'MAESTRO_DEL_SIGILO', 'Maestro del Sigilo', 'Sigilo absoluto', 'Pícaro capaz de desaparecer en combate.', 1.00, 76, 19, 13, 11, 11, 26, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Aprendió a desaparecer por completo en medio del combate, un fantasma que ataca y se desvanece antes de que nadie pueda reaccionar. — Defensa física (sigilo)'),
  (85, 'BUSCADOR_DE_TRAMPAS', 'Ingeniero de Trampas', 'Detector experto', 'Pícaro experto en detectar peligros ocultos.', 1.00, 76, 19, 13, 11, 11, 24, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Se volvió experto en detectar peligros que nadie más nota, desarmando amenazas ocultas antes de que puedan siquiera activarse. — Defensa física (control)'),
  (86, 'PICARO_ELEMENTAL', 'Maestro de Venenos', 'Filo elemental', 'Pícaro que combina sigilo con magia elemental.', 1.00, 76, 20, 13, 12, 11, 24, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Fusionó el sigilo de su clase con la magia elemental, volviendo cada golpe furtivo en un desastre elemental esperando a ocurrir. — Ataque físico y mágico'),
  (87, 'ACROBATA', 'Acróbata', 'Evasión perfecta', 'Pícaro de agilidad extrema, casi imposible de golpear.', 1.00, 76, 19, 13, 11, 11, 26, 10.00, 10.00, 10.00, 106, '2026-07-15T05:03:00.823Z', 'Llevó su agilidad a un extremo casi imposible; los golpes que no logran tocarlo son, de lejos, más que los que sí. — Defensa física (evasión)'),
  (88, 'OBISPO', 'Obispo', 'Curación mayor', 'Clérigo de rango superior con curaciones masivas.', 1.10, 83, 11, 18, 26, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Sus curaciones masivas pueden salvar a un equipo entero al borde de la derrota en un solo instante de fe. — Curación mayor'),
  (89, 'SANADOR_LEGENDARIO', 'Sanador Legendario', 'Milagro divino', 'Sanador capaz de salvar a cualquiera de la muerte.', 1.10, 102, 14, 22, 35, 30, 15, 10.00, 10.00, 10.00, 167, '2026-07-15T05:03:00.823Z', 'Es capaz de traer de vuelta a cualquiera del borde mismo de la muerte; los que pelean a su lado saben que nunca están realmente solos. — Curación suprema'),
  (90, 'DRUIDA_PRIMORDIAL', 'Druida Primordial', 'Naturaleza ancestral', 'Druida que domina la magia de la naturaleza.', 1.10, 83, 11, 18, 26, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Domina la magia de la naturaleza en su forma más pura y ancestral, una fuerza que precede a cualquier civilización. — Ataque y soporte mágico'),
  (91, 'PROTECTOR_DEL_BOSQUE', 'Protector del Bosque', 'Guardián natural', 'Druida dedicado a proteger a sus aliados con la naturaleza.', 1.10, 83, 11, 19, 24, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Dejó de atacar para dedicarse por completo a proteger a sus aliados, canalizando la naturaleza como un escudo viviente. — Soporte mágico (defensa)'),
  (92, 'CABALLERO_TEMPLARIO', 'Caballero Templario', 'Fe blindada', 'Templario de defensa y fe inquebrantables.', 1.10, 83, 11, 19, 23, 26, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Su defensa y su fe se volvieron inquebrantables por igual; ningún golpe logra hacer temblar ni su armadura ni su convicción. — Defensa mágica'),
  (93, 'PALADIN_DIVINO', 'Paladín Divino', 'Fe suprema', 'Templario que alcanza la magia divina avanzada.', 1.10, 83, 11, 19, 23, 25, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Alcanzó una magia divina tan avanzada que su sola presencia en el campo de batalla reconforta a sus aliados y aterra a sus enemigos. — Defensa mágica'),
  (94, 'GRAN_INQUISIDOR', 'Gran Inquisidor', 'Purga absoluta', 'Inquisidor temido por todas las criaturas oscuras.', 1.10, 83, 11, 18, 24, 27, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Es temido por todas las criaturas oscuras del reino; ninguna maldición ni corrupción sobrevive mucho tiempo cerca de su purga. — Ataque mágico (purificación)'),
  (95, 'ASCETA', 'Pontífice', 'Meditación total', 'Sacerdote que alcanza la iluminación interior.', 1.10, 83, 11, 18, 26, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Alcanzó una iluminación interior tan profunda que su sola meditación en combate se convierte en un santuario de curación para todo su equipo. — Curación suprema'),
  (96, 'EXORCISTA', 'Inquisidor Sagrado', 'Purificación', 'Sacerdote experto en exorcismos.', 1.10, 83, 11, 18, 24, 25, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Se volvió experto en expulsar la oscuridad de cualquier alma poseída, un especialista en purificación que la corrupción misma teme enfrentar. — Ataque mágico (purificación)'),
  (97, 'BENDITO', 'Bendito', 'Bendición eterna', 'Sacerdote que reparte bendiciones constantemente.', 1.10, 83, 11, 18, 26, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Reparte bendiciones constantemente, casi sin descanso, como si cada aliento suyo fuera una plegaria a favor de sus aliados. — Soporte mágico'),
  (98, 'HERBOLARIO_SAGRADO', 'Archidruida', 'Alquimia sagrada', 'Sacerdote experto en pociones y hierbas sagradas.', 1.10, 83, 11, 18, 26, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Se volvió experto en pociones y hierbas sagradas, encontrando en la alquimia una forma distinta de proteger a los suyos. — Soporte mágico (curación)'),
  (99, 'SACERDOTE_DEL_CAOS', 'Sacerdote del Caos', 'Fe corrompida', 'Sacerdote que abraza la magia oscura.', 1.10, 83, 11, 18, 24, 25, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Su fe se retorció hasta abrazar la magia oscura, conservando el poder de sanar mientras se entrega por completo a la corrupción. — Curación / ataque mágico oscuro'),
  (100, 'APOSTOL', 'Apóstol', 'Fe inquebrantable', 'Sacerdote venerado por sus curaciones incontables.', 1.10, 102, 14, 23, 31, 31, 15, 10.00, 10.00, 10.00, 167, '2026-07-15T05:03:00.823Z', 'Es venerado por curaciones que ya perdió la cuenta de cuántas veces salvaron a alguien de una muerte segura. — Curación suprema'),
  (101, 'VIDENTE', 'Vidente', 'Visión del futuro', 'Sacerdote capaz de predecir el futuro en combate.', 1.10, 83, 11, 18, 26, 24, 12, 10.00, 10.00, 10.00, 136, '2026-07-15T05:03:00.823Z', 'Aprendió a leer el combate antes de que ocurra, prediciendo los golpes enemigos como si ya los hubiera vivido antes. — Soporte mágico (predicción)')
