INSERT INTO tower_room_events (id, event_type, prompt_text, choice_a_label, choice_b_label, weight) VALUES
  (1, 'TRAP', 'El suelo cede bajo tus pies — una fosa de picos oxidados se abre de golpe.', 'Saltar e investigar qué hay más allá', 'Retroceder con cuidado', 10),
  (2, 'TRAP', 'Un hilo casi invisible cruza el pasillo. Al tensarlo, algo cruje sobre tu cabeza.', 'Cortar el hilo de un tajo', 'Rodearlo por el costado', 10),
  (3, 'VENDOR', 'Una figura encapuchada aguarda junto a un carromato destartalado, entre las sombras del Abismo.', 'Comerciar con el desconocido', 'Seguir de largo', 10),
  (4, 'VENDOR', 'El eco de monedas cayendo te guía hasta un pequeño campamento abandonado, con mercancía todavía tibia.', 'Revisar la mercancía', 'No tocar nada', 10),
  (5, 'SANCTUARY', 'Una luz tenue emana de un altar cubierto de musgo. El aire aquí se siente más liviano.', 'Descansar junto al altar', 'Seguir descendiendo', 10),
  (6, 'SANCTUARY', 'Encontrás una fuente de agua cristalina, imposible en un lugar tan profundo y oscuro.', 'Beber y descansar', 'Desconfiar y continuar', 10),
  (7, 'SECRET', 'Notás una grieta apenas visible entre las rocas, oculta tras una cortina de raíces.', 'Entrar por la grieta', 'Ignorarla', 10),
  (8, 'SECRET', 'Un reflejo metálico llama tu atención bajo un montón de escombros.', 'Cavar entre los escombros', 'No perder el tiempo', 10),
  (9, 'STORY', 'Un diario ajado yace junto a los restos de quien alguna vez lo escribió. Las últimas palabras son casi ilegibles.', 'Leer el diario', 'Dejarlo donde está', 10),
  (10, 'STORY', 'Grabados en la piedra cuentan, en un idioma casi olvidado, la historia de quienes construyeron este lugar.', 'Detenerse a descifrarlos', 'No hay tiempo para esto', 10),
  (11, 'TRAP', 'Una losa se hunde bajo tu peso, y un chasquido metálico resuena desde las paredes.', 'Correr hacia adelante', 'Quedarte quieto', 10),
  (12, 'TRAP', 'El aire se vuelve pesado, casi venenoso, cerca de un montículo de huesos apilados con cuidado.', 'Acercarte a investigar', 'Mantener la distancia', 10),
  (13, 'TRAP', 'Una telaraña gruesa, del tamaño de una puerta, cubre el paso — algo se mueve en el centro.', 'Cortarla de un tajo', 'Buscar otro camino', 10),
  (14, 'TRAP', 'El eco de tus propios pasos empieza a llegar un instante tarde, como si algo los repitiera.', 'Girarte de golpe', 'Acelerar el paso', 10),
  (15, 'TRAP', 'Un símbolo grabado en el suelo brilla tenue en cuanto lo pisás.', 'Completar el símbolo', 'Borrarlo con el pie', 10),
  (16, 'TRAP', 'Gotea algo espeso y oscuro desde el techo, justo sobre el camino que seguías.', 'Pasar de todos modos', 'Rodear la mancha', 10),
  (17, 'VENDOR', 'Un carrito destartalado avanza solo, empujado por nadie, con mercancía tintineando.', 'Detenerlo y revisar', 'Dejarlo pasar', 10),
  (18, 'VENDOR', 'Alguien silba una melodía familiar desde una hoguera pequeña, apartada del camino.', 'Acercarte al fuego', 'Seguir de largo', 10),
  (19, 'VENDOR', 'Una mano pálida se asoma desde una grieta, sosteniendo algo brillante.', 'Tomar lo que ofrece', 'Ignorar la mano', 10),
  (20, 'VENDOR', 'Un cartel de madera, mal escrito, anuncia "TRUEQUES" con una flecha hacia la oscuridad.', 'Seguir la flecha', 'No hacerle caso', 10),
  (21, 'VENDOR', 'El sonido de monedas cayendo en cascada te guía hacia una cueva lateral.', 'Entrar a la cueva', 'Seguir el camino principal', 10),
  (22, 'VENDOR', 'Una figura envuelta en velos ofrece intercambiar "algo por algo", sin decir qué.', 'Aceptar el trato', 'Rechazar la oferta', 10),
  (23, 'SANCTUARY', 'Un círculo de hongos luminosos rodea un claro extrañamente tranquilo.', 'Entrar al círculo', 'Rodearlo por fuera', 10),
  (24, 'SANCTUARY', 'El frío del Abismo desaparece de golpe cerca de una estatua sin rostro.', 'Apoyarte en la estatua', 'Seguir de largo', 10),
  (25, 'SANCTUARY', 'Un estanque de aguas quietas refleja un cielo que no debería existir tan abajo.', 'Mirar el reflejo y descansar', 'No mirar, seguir', 10),
  (26, 'SANCTUARY', 'Encontrás una pequeña hoguera ya encendida, sin nadie alrededor, ardiendo tranquila.', 'Sentarte junto al fuego', 'Apagarla y continuar', 10),
  (27, 'SANCTUARY', 'Un árbol pálido, imposible en la oscuridad, deja caer una fruta madura a tus pies.', 'Comer la fruta', 'Dejarla ahí', 10),
  (28, 'SANCTUARY', 'El eco de una canción de cuna resuena suave desde algún lugar cercano.', 'Seguir el sonido y descansar', 'Taparte los oídos y avanzar', 10),
  (29, 'SECRET', 'Un pasadizo angosto se esconde detrás de una cascada de agua subterránea.', 'Cruzar la cascada', 'Seguir de largo', 10),
  (30, 'SECRET', 'Las marcas de garras en la pared parecen formar, casi, un mapa.', 'Seguir las marcas', 'No confiar en ellas', 10),
  (31, 'SECRET', 'Un escalón suena hueco bajo tu bota, distinto a los demás.', 'Forzar el escalón', 'Pisar con cuidado y seguir', 10),
  (32, 'SECRET', 'Una puerta diminuta, del tamaño de un puño, está tallada en la roca — imposible de abrir a mano.', 'Buscar la forma de abrirla', 'Dejarla como curiosidad', 10),
  (33, 'SECRET', 'El polvo del suelo dibuja un patrón que no parece casual.', 'Seguir el patrón', 'Barrerlo con el pie', 10),
  (34, 'SECRET', 'Una corriente de aire fresco sale de una rendija que no debería tener salida al exterior.', 'Ensanchar la rendija', 'Ignorar la corriente', 10),
  (35, 'STORY', 'Una armadura vacía, apoyada contra la pared, todavía sostiene una espada clavada en el suelo.', 'Examinar la armadura', 'Rendirle respeto y seguir', 10),
  (36, 'STORY', 'Alguien talló su propio nombre, una y otra vez, en la misma piedra.', 'Leer el nombre', 'No detenerte', 10),
  (37, 'STORY', 'Un juguete infantil, gastado por el tiempo, yace solo en medio del pasillo.', 'Recogerlo', 'Dejarlo donde está', 10),
  (38, 'STORY', 'Las paredes de esta sala están cubiertas de fechas talladas, contando algo que ya no continúa.', 'Contar las fechas', 'Seguir sin mirar', 10),
  (39, 'STORY', 'Un mural descolorido muestra una ciudad entera, tragada por la oscuridad.', 'Estudiar el mural', 'Continuar el descenso', 10),
  (40, 'STORY', 'Cadenas rotas cuelgan del techo, todavía balanceándose levemente.', 'Investigar las cadenas', 'Pasar rápido, sin mirar arriba', 10)
INSERT INTO artisans (id, code, name, specialty, zone_id, description) VALUES
  (1, 'ALQUIMISTA', 'Lyra la Alquimista', 'ALQUIMISTA', NULL, 'Prepara pociones y consumibles mágicos.'),
  (2, 'COCINERO', 'Aldric el Cocinero', 'COCINERO', NULL, 'Cocina alimentos que otorgan bonificaciones en combate.'),
  (3, 'HERRERO', 'Maestro Goreth', 'HERRERO', NULL, 'Forja armas y armaduras para el Guerrero.'),
  (4, 'JOYERO', 'Cedric el Joyero', 'JOYERO', NULL, 'Crea accesorios y joyas para cualquier clase.'),
  (5, 'PELETERO', 'Bram el Peletero', 'PELETERO', NULL, 'Trabaja cuero y pieles para Pícaro y Arquero.'),
  (6, 'SASTRE', 'Faeron el Sastre', 'SASTRE', NULL, 'Confecciona túnicas y báculos para Mago y Sacerdote.')
