  (14, 42, 'Vacío del Combate', 'ONCE_PER_COMBAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"survive_hp":1}'::jsonb, 'Una vez por combate, si su HP llega a 0, sobrevive con 1 HP.', FALSE),
