  (60, 22, 'Instinto Letal', 'PASSIVE_CONDITIONAL', NULL, FALSE, 'CRIT_CHANCE', 10.00, 'TARGET_HP_ABOVE_SELF', NULL, NULL, 'Contra enemigos con más HP que él, +10% de probabilidad de crítico.', FALSE),
  (61, 23, 'Manos Rápidas', 'MODIFIES_SKILL', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"extra_action_reduced_chance","skill_code":"PICARO_ROBAR","penalty_percent":50}'::jsonb, 'Su skill Robar no consume el turno completo: puede volver a actuar con -50% de probabilidad de éxito ese mismo turno.', FALSE),
  (62, 24, 'Toxina Base', 'PASSIVE_STAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"dot_damage_bonus_percent":10}'::jsonb, 'Sus DOT hacen 10% más daño por turno.', FALSE),
  (63, 25, 'Terreno Preparado', 'MODIFIES_SKILL', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"instant_activation_same_turn","skill_code":"ESPECIALISTA_TRAMPAS_TRAMPA"}'::jsonb, 'Su Trampa tarda un turno menos en activarse (plantar y activar en el mismo turno).', FALSE),
  (64, 78, 'Nunca Visto', 'PASSIVE_CONDITIONAL', NULL, FALSE, 'EVASION', 20.00, 'IS_INVISIBLE', NULL, NULL, '+20% de probabilidad de esquivar cualquier ataque mientras tenga invisibilidad activa.', FALSE),
  (65, 79, 'Fusión de Sombras', 'PASSIVE_STAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"dot_can_crit":["DARK"]}'::jsonb, 'Sus DOT oscuros pueden hacer crítico.', FALSE),
  (66, 87, 'Casi Intocable', 'PASSIVE_STAT', NULL, FALSE, 'EVASION', 15.00, NULL, NULL, NULL, '+15% de evasión permanente.', FALSE),
  (67, 75, 'Un Golpe, Un Final', 'PASSIVE_CONDITIONAL', NULL, FALSE, NULL, NULL, 'TARGET_HP_BELOW', 15.00, '{"effect":"guarantee_crit"}'::jsonb, 'Contra enemigos con menos de 15% HP, sus ataques son crítico garantizado.', FALSE),
  (68, 76, 'Cazador de Jefes', 'PASSIVE_CONDITIONAL', NULL, FALSE, 'DAMAGE_DEALT', 20.00, 'TARGET_IS_BOSS', NULL, NULL, '+20% de daño contra jefes de quest o de piso de torre.', FALSE),
  (69, 80, 'Leyenda Viva', 'MODIFIES_SKILL', NULL, FALSE, NULL, NULL, NULL, NULL, '{"skill_code":"PICARO_ROBAR","success_bonus_percent":15}'::jsonb, '+15% de probabilidad de éxito adicional en Robar.', FALSE),
  (70, 81, 'Ojo de Tesoros', 'MODIFIES_SKILL', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"rare_drop_chance_bonus","skill_code":"PICARO_ROBAR"}'::jsonb, 'Al robar con éxito, probabilidad extra de obtener el drop más raro del monstruo en vez de uno al azar.', FALSE),
  (71, 77, 'Síntesis Tóxica', 'PASSIVE_STAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"poisons_stack_independently":true}'::jsonb, 'Sus 5 venenos pueden coexistir en el mismo objetivo sin reemplazarse entre sí.', FALSE),
  (72, 86, 'Filo Elemental', 'ON_COMBAT_START', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"imbue_random_element_on_basic_attacks"}'::jsonb, 'Sus ataques básicos se imbuyen con un elemento al azar al empezar cada combate.', FALSE),
  (73, 82, 'A Sueldo', 'ON_VICTORY_REWARD', NULL, FALSE, 'GOLD', 10.00, NULL, NULL, NULL, '+10% de oro ganado en cada victoria.', FALSE),
  (74, 83, 'Sentido de Mazmorra', 'ON_VICTORY_REWARD', NULL, FALSE, 'DUNGEON_COINS', 15.00, NULL, NULL, NULL, '+15% de monedas de mazmorra ganadas en la Torre Infinita.', FALSE),
  (75, 84, 'Fantasma de Combate', 'PASSIVE_STAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"invisibility_duration_bonus_turns":1}'::jsonb, 'Su invisibilidad dura 1 turno extra.', FALSE),
  (76, 85, 'Detector Nato', 'MODIFIES_SKILL', NULL, FALSE, NULL, NULL, NULL, NULL, '{"skill_code":"ESPECIALISTA_TRAMPAS_DESACTIVAR","success_rate_percent":100}'::jsonb, 'Su Desactivar Trampas nunca falla (100% de éxito).', FALSE),
  (77, 26, 'Fe Instantánea', 'ON_HEAL_CAST', 10.00, FALSE, NULL, NULL, NULL, NULL, '{"effect":"double_heal"}'::jsonb, '10% de probabilidad de que una curación se duplique.', FALSE),
  (78, 27, 'Equilibrio Natural', 'PASSIVE_STAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"no_extra_mana_switching_dmg_heal"}'::jsonb, 'Alterna entre daño y curación sin costo de maná adicional por el cambio.', FALSE),
  (79, 28, 'Escudo de Fe', 'ON_DEFEND', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"grant_small_shield_random_ally"}'::jsonb, 'Al usar Defender, también otorga un escudo pequeño a un aliado al azar.', FALSE),
  (80, 29, 'Milagro', 'PASSIVE_CONDITIONAL', NULL, FALSE, 'HEAL_POWER', 20.00, 'TARGET_HP_BELOW', 30.00, NULL, 'Sus curas a aliados con menos de 30% HP curan 20% más.', FALSE),
  (81, 30, 'Juicio', 'PASSIVE_CONDITIONAL', NULL, FALSE, NULL, NULL, 'TARGET_CATEGORY_IN', NULL, '{"effect":"ignore_magic_resistance","categories":["DEMONIO","ESPECTRO","MUERTO_VIVIENTE"]}'::jsonb, 'Su daño contra enemigos oscuros o no-muertos ignora la resistencia mágica.', FALSE),
  (82, 88, 'Curación en Cadena', 'ON_HEAL_CAST', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"heal_adjacent_lowest_hp_ally_small"}'::jsonb, 'Su cura principal también cura levemente al aliado adyacente con menos HP.', FALSE),
  (83, 97, 'Plegaria Constante', 'PASSIVE_STAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"no_buff_target_limit":true}'::jsonb, 'Sus bendiciones no tienen límite de aliados con el buff activo a la vez.', FALSE),
  (84, 100, 'Incontables Milagros', 'ONCE_PER_COMBAT', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"next_heal_cannot_fail_or_be_interrupted"}'::jsonb, 'Una vez por combate, su próxima curación no puede fallar ni ser interrumpida.', FALSE),
  (85, 90, 'Ciclo de Vida', 'ON_HEAL_CAST', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"restore_mana_on_heal"}'::jsonb, 'Recupera maná extra cada vez que cura a un aliado.', FALSE),
  (86, 91, 'Escudo Natural', 'TEAM_AURA', NULL, FALSE, 'EVASION', 5.00, NULL, NULL, '{"target":"protected_ally"}'::jsonb, 'El aliado que protege también gana +5% de evasión.', FALSE),
  (87, 98, 'Alquimia Sagrada', 'ON_CRAFT', NULL, FALSE, NULL, 10.00, NULL, NULL, '{"effect":"potion_potency_bonus"}'::jsonb, 'Las pociones que craftea tienen 10% más potencia.', FALSE),
  (88, 92, 'Fe Blindada', 'PASSIVE_CONDITIONAL', NULL, FALSE, NULL, NULL, 'SELF_HP_ABOVE', 50.00, '{"effect":"immune_def_debuffs"}'::jsonb, 'Inmune a debuffs de DEF mientras tenga más de 50% HP.', FALSE),
  (89, 93, 'Presencia Divina', 'TEAM_AURA', NULL, FALSE, 'CRIT_CHANCE', 5.00, NULL, NULL, NULL, 'Todo el equipo gana +5% de probabilidad de crítico mientras esté vivo.', FALSE),
  (90, 89, 'Nunca Solos', 'ON_REVIVE_CAST', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"heal_team_small_on_revive"}'::jsonb, 'Su Revivir también cura levemente a todo el equipo al activarse.', FALSE),
  (91, 101, 'Premonición', 'PASSIVE_STAT', NULL, FALSE, 'EVASION', 10.00, NULL, NULL, NULL, '10% de probabilidad de esquivar cualquier ataque, incluso sin usar Predicción.', FALSE),
  (92, 95, 'Santuario Interior', 'ON_HEAL_CAST', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"cleanse_one_debuff_each_ally","skill_code":"SANADOR_LEGENDARIO_MEDITACION"}'::jsonb, 'Su Meditación también limpia un debuff de cada aliado al lanzarse.', FALSE),
  (93, 99, 'Fe Retorcida', 'ON_HEAL_CAST', NULL, FALSE, NULL, NULL, NULL, NULL, '{"effect":"heal_also_damages_enemies_small"}'::jsonb, 'Sus curaciones también dañan levemente a los enemigos.', FALSE),
  (94, 94, 'Purga Absoluta', 'PASSIVE_CONDITIONAL', NULL, FALSE, NULL, NULL, 'TARGET_CATEGORY_IN', NULL, '{"effect":"ignore_all_resistance","categories":["DEMONIO","ESPECTRO","MUERTO_VIVIENTE"]}'::jsonb, 'Su daño contra criaturas oscuras ignora toda resistencia.', FALSE),
  (95, 96, 'Exorcismo Perfecto', 'MODIFIES_SKILL', NULL, FALSE, NULL, NULL, NULL, NULL, '{"skill_code":"EXORCISTA_APOYO","success_rate_percent":100}'::jsonb, 'Su Exorcismo (Exorcismo Supremo) nunca falla.', FALSE),
  (96, 9, 'Ira Creciente', 'ON_DAMAGE_TAKEN', NULL, FALSE, 'ATK', 3.00, NULL, NULL, '{"reset_on":"full_heal","stack_per_hp_lost_percent":10}'::jsonb, '+3% ATK acumulativo por cada 10% de HP perdido; se reinicia al curarse por completo.', TRUE),
  (97, 50, 'Sed de Sangre', 'ON_KILL', NULL, FALSE, 'ATK', 5.00, NULL, NULL, '{"reset_on":"never_within_combat","stack_amount":1}'::jsonb, 'Cada kill otorga un stack permanente de +5% ATK por el resto del combate.', TRUE),
  (98, 51, 'Caos Encarnado', 'ON_KILL', NULL, FALSE, 'ATK', 5.00, NULL, NULL, '{"reset_on":"never_within_combat","stack_amount":1,"also_stat_code":"DAMAGE_TAKEN","also_percent_per_stack":2}'::jsonb, 'Los stacks de Sed de Sangre también aumentan levemente el daño que recibe, +2% por stack (riesgo/recompensa).', TRUE),
  (99, 69, 'Trofeos de Caza', 'ON_KILL', NULL, FALSE, 'DAMAGE_DEALT', 1.00, NULL, NULL, '{"reset_on":"never_within_combat","stack_amount":1}'::jsonb, '+1% de daño acumulable por cada kill logrado durante el combate.', TRUE)
INSERT INTO class_masters (id, class_id, name, intro_dialogue, guild_dialogue) VALUES
  (1, 1, 'Kadric, el Veterano', '¡Cuidado! — un bandido cae ante ti antes de que termine de hablar. Kadric baja el brazo, sorprendido. "Hace tiempo que no veía a alguien sostener el filo con tanta convicción. Ven al gremio cuando puedas."', 'Todavía sostengo el filo mejor que la mayoría de los novatos que veo pasar. Pero tú... tú ya no eres un novato.'),
  (2, 8, 'Dama Isolde, Guardiana del Juramento', 'Isolde retrocede un paso, cediendo terreno ante la bestia — hasta que apareces tú. "Pocos soportan el peso de una armadura completa sin quebrarse. Bienvenido al gremio, caballero."', 'El juramento no se lleva en la armadura. Se lleva en no romperse cuando pesa. Tú ya lo sabes.'),
  (3, 45, 'Sumo Paladín Aurelio', 'La luz que envuelve a Aurelio parpadea, casi extinguida — y se estabiliza en cuanto derrotas a lo que lo acosaba. "La luz no elige a cualquiera. Tú la sostuviste sin que te consumiera."', 'Cada paladín cree que la luz lo eligió. Pocos entienden que la luz solo espera a ver quién no se quiebra primero.'),
  (4, 46, 'La Venerable Seraphine', 'Seraphine no pide ayuda — la ofrece, incluso rodeada. Cuando termina el combate, te mira con algo parecido al reconocimiento. "El cielo mismo reconoce tu armadura, ahora."', 'Pocos alcanzan la gracia celestial y siguen de pie. Menos todavía la llevan sin arrogancia. Tú, por ahora, eres de los pocos.'),
  (5, 2, 'Archimago Thelen', 'Un círculo arcano inestable amenaza con colapsar sobre Thelen — lo estabilizas justo a tiempo. "El poder sin estudio es solo ruido. Tú ya entendiste eso. Ven, hay mucho que enseñarte todavía."', 'La magia no es fuerza. Es paciencia con forma de fuego. Todavía te falta paciencia — pero eso se enseña.'),
  (6, 6, 'Hermano Kaelen', 'Un grupo de bandidos rodea a Kaelen, que pelea sin armas contra varios a la vez — hasta que ayudas a inclinar la balanza. "Pocos entienden que las manos vacías pueden ser el arma más honesta. Ven al gremio, quiero enseñarte lo que sé."', 'El puño no miente. La espada puede ocultar la intención — el puño, nunca.'),
  (7, 7, 'Roland, Filo Perfecto', 'Roland duela contra dos oponentes con una elegancia que empieza a fallarle por el cansancio — tu ayuda inclina el combate. "Hace mucho que no veía a alguien mover el acero con esa precisión. Bienvenido."', 'La espada mágica no perdona errores. Tú todavía no cometiste ninguno que yo haya visto.'),
  (8, 9, 'Gorrath, Puño de Furia', 'Gorrath ruge en medio de una masacre, apenas conteniendo su propia rabia — hasta que peleas a su lado. "La furia sin control te devora. La tuya... la tuya todavía te obedece. Interesante."', 'Cuidado con la furia. Yo dejé de contar cuántas veces casi me devoró.'),
  (9, 10, 'Vellandra, la Arcana Marcial', 'Un hechizo se le escapa de las manos a Vellandra en pleno combate — lo estabilizas justo antes de que la lastime a ella misma. "Combinar espada y magia exige un control que pocos tienen. Tú lo tienes. Ven al gremio."', 'La magia sin disciplina es un arma que se vuelve contra ti. Yo aprendí eso de la peor manera.'),
  (10, 38, 'Gran Maestro Senn', 'Senn no necesita moverse para desviar cada golpe — hasta que ve algo en ti que lo hace bajar la guardia por primera vez en años. "Hace décadas que nadie me sorprende. Tú lo hiciste hoy."', 'El puño maestro no busca golpear primero. Busca no necesitar hacerlo.'),
  (11, 39, 'Umbra, el Puño Caído', 'Umbra pelea con golpes que dejan un rastro de sombra — te reconoce como alguien que también camina cerca del límite. "La oscuridad no te consumió todavía. Eso te hace peligroso. Ven, hablemos."', 'Todo puño oscuro empezó como un puño honesto. La pregunta es cuándo dejas de notar la diferencia.'),
  (12, 40, 'Doran, Puño de Piedra', 'Doran golpea el suelo y la tierra misma responde — te mira con aprobación cuando devuelves el golpe con la misma fuerza. "La tierra recuerda cada golpe verdadero. La tuya te recordará a ti."', 'No soy yo quien golpea. Es la montaña, a través de mí. Aprende a escuchar eso.'),
  (13, 41, 'Hermana Lyth', 'Una luz cálida rodea los puños de Lyth mientras golpea con precisión casi ritual — te invita a unirte al combate y la luz no vacila ante ti. "Pocos canalizan lo divino sin perder la humildad. Tú todavía la tienes."', 'La energía divina en los puños es un préstamo, no una posesión. No lo olvides nunca.'),
  (14, 42, 'El Silencioso', 'Nadie recuerda su nombre real — solo que detiene ejércitos con un solo golpe. Hoy pelea a tu lado, en silencio, y al final asiente una sola vez.', 'No hablo mucho. Cuando lo hago, es porque ya lo pensé demasiado.'),
  (15, 43, 'Corvinne, Filo Sin Nombre', 'Corvinne corta el aire mismo con una técnica que nadie más domina — te mide con la mirada mientras peleas a su lado. "Pocas espadas se mueven como la tuya. La mía, hace mucho que dejó de sorprenderse. Hoy lo hizo."', 'El filo perfecto no es el más afilado. Es el que nunca duda.'),
  (16, 44, 'Sir Malachor', 'Una armadura ennegrecida por magia oscura protege a Malachor mientras cae en combate — lo ayudas y algo en su mirada cambia. "La oscuridad me consumió hace tiempo. Todavía no te consumió a ti. Aprovéchalo."', 'No vine a redimirme. Vine a enseñarte a sobrevivir a lo que yo no pude evitar.'),
  (17, 47, 'Sir Vanther, el Caído', 'Vanther pelea con luz corrompida, oscura pero todavía reconocible como sagrada alguna vez — te mira con algo entre desconfianza y reconocimiento. "Caí de la luz y todavía la uso, corrompida. Tú eliges tu propio camino. Que sea mejor que el mío."', 'No vine a que me admires. Vine a que no cometas el mismo error que yo.'),
  (18, 48, 'Coraza, el Inquebrantable', 'Una armadura que parece imposible de perforar recibe golpe tras golpe sin ceder — hasta que tú también aguantas a su lado. "Pocos entienden que la verdadera defensa no es no caer. Es no romperse. Bienvenido."', 'Mi armadura no es indestructible. Yo tampoco. Pero ninguno de los dos lo demuestra fácil.'),
  (19, 49, 'Sir Vaelith, Sangre de Dragón', 'Escamas de dragón cubren la armadura de Vaelith, brillando con un calor que no debería existir — pelea a tu lado y algo antiguo parece reconocerte. "La sangre de dragón no se hereda. Se gana. Tú ya empezaste a ganarla."', 'Cada escama que llevo costó algo. No preguntes qué, todavía no estás listo para esa respuesta.'),
  (20, 50, 'Titán Furioso, el que Bebió del Cáliz', 'Algo golpea con una furia que ya no parece del todo suya — te reconoce como alguien que entiende ese límite. "El cáliz de la furia te da poder. También te quita algo. Tú todavía no perdiste lo importante."', 'No pregunto qué bebiste para llegar hasta acá. Yo tampoco quiero recordar qué bebí yo.'),
  (21, 51, 'Kharzuk, Heraldo del Caos', 'Algo en los golpes de Kharzuk ya no sigue ninguna lógica reconocible — y sin embargo, pelea a tu lado con una precisión aterradora. "El caos no elige a cualquiera. Tú ya lo escuchaste, ¿no es cierto?"', 'No busco que me entiendas. Busco que sobrevivas a lo que viene después de escuchar al caos.'),
  (22, 52, 'Thessaly, Filo Arcano', 'Thessaly combina estocadas con destellos de magia en un ritmo casi imposible de seguir — peleas a su lado sin perder el paso. "Pocos combinan ambas artes sin perder ninguna. Tú las tienes a las dos, intactas."', 'La espada y la magia se pelean por tu atención. Aprende a no elegir entre ellas.'),
  (23, 53, 'Profesor Endrick', 'Endrick defiende unas ruinas de un peligro que él mismo despertó sin querer — lo ayudas justo a tiempo. "Toda ruina esconde algo que preferiría seguir dormido. Tú ya demostraste que puedes con eso."', 'Cada reliquia que traigo casi me mata una vez. Aprende de mis errores, no los repitas.'),
  (24, 16, 'Torvin, el Rastreador', 'Torvin sigue el rastro de una bestia peligrosa, casi perdiéndolo por el cansancio — lo ayudas a acorralarla. "Cazar no es matar. Es entender antes que el otro se mueva. Tú ya entiendes eso."', 'Cada flecha que suelto ya sabía dónde iba a caer antes de soltarla.'),
  (25, 17, 'Lyra, Ojo Certero', 'Lyra apunta desde lejos mientras algo se acerca demasiado rápido para su gusto — tu ayuda le da el segundo que necesitaba. "Un disparo, un objetivo. Tú entiendes la paciencia que eso exige."', 'La distancia no es cobardía. Es respeto por lo que estás a punto de hacer.'),
  (26, 18, 'Aldric del Bosque Gris', 'Aldric combina flechas y curaciones improvisadas mientras protege a un grupo herido — te sumas y el balance vuelve. "Un ranger no elige entre atacar o proteger. Elige hacer ambas cosas bien."', 'El bosque me enseñó que la fuerza sola nunca alcanza. Aprende eso pronto.'),
  (27, 19, 'Nyx, Sombra con Filo', 'Nyx combina flechas oscuras con golpes casi invisibles — peleas a su lado sin verla la mitad del tiempo. "La oscuridad no es ausencia de luz. Es una herramienta más. Tú ya la usas bien."', 'Nadie me ve venir. Tú tampoco, la mayoría de las veces.'),
  (28, 20, 'Sylvaeril', 'Sylvaeril defiende un claro sagrado del bosque con flechas cargadas de magia natural — peleas a su lado y el bosque no te rechaza. "El bosque elige a quién protege. Hoy te eligió a ti también."', 'Cinco arcos élficos no se encuentran. Se ganan, uno por uno.'),
  (29, 62, 'Vantha, la Invisible', 'Un disparo perfecto sale de la nada, y Vantha aparece un segundo después como si nunca hubiera estado ausente — peleas a su lado sin entender del todo cómo. "Si me ves antes del disparo, hice algo mal."', 'El sigilo perfecto no es no estar. Es que nadie note cuándo dejaste de estarlo.'),
  (30, 63, 'Bram Pólvora', 'Una flecha explota más cerca de Bram de lo que planeaba — lo sacas de la línea de fuego justo a tiempo. "Cada flecha explosiva es un cálculo. A veces el cálculo falla. Hoy tú me salvaste del error."', 'Prefiero un poco de riesgo a un combate aburrido. Tú pareces pensar igual.'),
  (31, 64, 'Serel, Colmillo Lento', 'Serel dispara flechas venenosas mientras algo grande se acerca demasiado rápido para que el veneno haga efecto a tiempo — lo ayudas a ganar esos segundos. "El veneno no necesita prisa. Solo necesita tiempo. Tú me lo diste."', 'La muerte lenta no es crueldad. Es paciencia disfrazada de piedad.'),
  (32, 66, 'Ilyana, Flecha de Luz', 'Flechas de luz pura caen sobre un grupo de criaturas oscuras mientras Ilyana empieza a flaquear — peleas a su lado y la luz se sostiene. "La luz elige a sus arqueros con cuidado. Tú ya demostraste por qué te eligió."', 'Cada flecha de luz que disparo es una plegaria silenciosa. No siempre sé si la escuchan.'),
  (33, 67, 'Gareth Acero Pesado', 'Gareth reemplaza su arco por una ballesta pesada mientras enfrenta algo que un arco normal no perforaría — peleas a su lado y el disparo por fin conecta. "El arco es velocidad. La ballesta es certeza. Elegí la certeza, y no me arrepiento."', 'Cambiar de arma no es debilidad. Es reconocer qué necesita el momento.'),
  (34, 68, 'Kessa Tormenta', 'Flechas cargadas de rayo saltan entre varios enemigos a la vez, casi descontroladas — ayudas a Kessa a redirigirlas. "El rayo en una flecha no perdona errores de cálculo. Tú evitaste el mío."', 'Cada flecha de rayo que suelto es una apuesta. Hasta ahora, gané casi todas.'),
  (35, 69, 'Orrin, el de las Mil Presas', 'Orrin enfrenta a una bestia que ya cazó antes y que ahora volvió más fuerte — peleas a su lado y la historia se repite, esta vez a su favor. "Cada presa que cazo me enseña algo nuevo. Esta te la debo a ti."', 'Mil presas después, todavía aprendo algo de cada una que se me escapa.'),
  (36, 70, 'Thalindor', 'Thalindor sostiene un arco que parece más viejo que el bosque mismo — peleas a su lado y el arco no te trata como a un extraño. "Este arco vio caer imperios. Hoy te vio a ti, y no fue lo peor que vio."', 'La sabiduría élfica no se apura. Lamentablemente, algunos peligros sí.'),
  (37, 71, 'Kaelith, Raíz y Flecha', 'Kaelith canaliza magia primordial del bosque mismo mientras algo intenta corromper el área — peleas a su lado y la corrupción retrocede. "El bosque primordial no olvida a quien lo defiende. Ya no te va a olvidar a ti tampoco."', 'La naturaleza pura no es gentil. Es justa, que es distinto.'),
  (38, 72, 'Bren Escudo Verde', 'Bren se interpone entre sus aliados y el peligro usando magia natural defensiva — peleas a su lado protegiendo a los mismos que él protege. "Proteger no es débil. Es elegir a quién le importas más que a ti mismo."', 'Cada aliado que protejo es una razón más para seguir de pie.'),
  (39, 73, 'Xaltheris', 'Xaltheris pelea consumido por una oscuridad que ya casi no controla — lo ayudas a contenerla el tiempo suficiente para ganar. "La oscuridad que uso ya no me pertenece del todo. Gracias por recordarme que todavía puedo controlarla."', 'No pregunto si confías en mí. Yo tampoco confío del todo en mí mismo.'),
  (40, 74, 'Aelendor, Corona Ancestral', 'Aelendor defiende el corazón mismo del bosque ancestral con una autoridad que nadie cuestiona — peleas a su lado y el bosque entero parece atento. "Gobernar un bosque no es tener poder sobre él. Es merecer su confianza, día a día."', 'La corona que llevo no es mía. Es del bosque. Yo solo la cuido.'),
  (41, 12, 'Maldris, el Cuervo Pálido', 'Un ejército de esqueletos rodea a Maldris, que apenas logra mantenerlos bajo control mientras algo más grande se acerca — lo ayudas justo a tiempo. "La muerte obedece a quien no le teme. Tú tampoco le temes, ¿verdad?"', 'No levanto muertos por crueldad. Los levanto porque alguien tiene que recordarlos.'),
  (42, 13, 'Yssara, la que Llama', 'Yssara invoca aliados uno tras otro, cada vez más débil — hasta que peleas junto a sus invocaciones y el combate se inclina. "Invocar no es reemplazar tu propia fuerza. Es multiplicarla. Tú ya lo entiendes."', 'Cada aliado que invoco es un pedazo mío. Aprende a no dar más de lo que puedes perder.'),
  (43, 14, 'Fenrik, el que Doma Cuatro Vientos', 'Fenrik lanza fuego, hielo y rayo casi al mismo tiempo, perdiendo el control por un instante — lo estabilizas con tu propio ataque. "Dominar un elemento es fuerza. Dominar varios es un equilibrio que pocos sostienen."', 'Cada elemento tiene su propio temperamento. Aprende a escucharlos antes de que te escuchen a ti.'),
  (44, 15, 'Seraphiel, Voz de lo Alto', 'Una luz cegadora rodea a Seraphiel mientras contiene algo que no debería estar aquí abajo — peleas a su lado y la luz no te rechaza. "Lo divino no se impone. Se te ofrece. Tú ya lo aceptaste sin saberlo."', 'El poder supremo no es tuyo. Es prestado. No lo olvides nunca.'),
  (45, 31, 'Ignara, Llama Eterna', 'Ignara arde literalmente mientras pelea, controlando el fuego que la envuelve — te reconoce cuando devuelves el golpe con la misma intensidad. "El fuego no perdona a quien duda. Tú no dudaste."', 'Doscientas muertes al fuego me costó este dominio. Espero que a ti te cueste menos.'),
  (46, 32, 'Wrenna, Escarcha Eterna', 'El hielo de Wrenna casi la encierra a ella misma en su propio hechizo — la liberas justo a tiempo. "El hielo no mata rápido. Mata seguro. Tú ya entiendes esa paciencia."', 'Congelar algo no es destruirlo. Es esperar el momento correcto para romperlo.'),
  (47, 33, 'Zarek, Tormenta Viva', 'Rayos saltan sin control alrededor de Zarek, casi golpeándolo a él mismo — lo ayudas a canalizarlos de vuelta al enemigo. "El rayo no elige a quién golpea. Tú aprendiste a apuntar igual."', 'Doscientos rayos después, todavía me sorprende no haberme matado yo mismo.'),
  (48, 34, 'Marejada', 'El agua responde a cada gesto suyo con una precisión casi líquida — peleas a su lado sin que ni una gota caiga fuera de lugar. "El agua cede ante todo y no pierde nunca. Aprende esa lección."', 'Nadie recuerda mi nombre de antes del agua. Ya no importa quién era.'),
  (49, 35, 'Grundar, Puño de Montaña', 'La tierra misma se levanta para proteger a Grundar de una emboscada — peleas a su lado y las rocas no te tratan como enemigo. "La tierra es paciente. Yo aprendí a serlo también. Tú ya empiezas a entenderlo."', 'Doscientos golpes de tierra después, todavía respeto cada roca que levanto.'),
  (50, 36, 'Silva, Viento Sin Nombre', 'Silva se mueve casi tan rápido como el viento que controla — apenas la sigues, pero alcanza para ayudarla. "El viento no se detiene para nadie. Tú casi lo alcanzaste."', 'Nunca me quedo en un lugar mucho tiempo. Este gremio es la excepción, por ahora.'),
  (51, 37, 'Lucian, Portador de Luz', 'Una luz cegadora rodea a Lucian mientras repele algo que la oscuridad casi consume — peleas a su lado sin que la luz te lastime. "La luz no juzga a quien la usa bien. Tú la usas bien."', 'Doscientas veces usé la luz para matar. Todavía no sé si eso me hace mejor o peor persona.'),
  (52, 54, 'El Rey sin Nombre', 'Un ejército entero de no-muertos obedece un solo gesto suyo — peleas a su lado y por un instante también pareces parte de ese ejército. "No gobierno a los muertos. Los muertos me siguen porque ya no tienen nada mejor que hacer."', 'Un reino de huesos no reemplaza uno de carne. Nunca lo olvides.'),
  (53, 55, 'Ashkeloth', 'Ashkeloth ya no respira, y sin embargo pelea con una precisión que ningún vivo podría sostener tanto tiempo — te mira con algo parecido a la curiosidad de alguien que hace siglos no siente nada. "La muerte no fue el final que esperaba. Fue apenas el comienzo de algo más aburrido."', 'No te apures a envidiar la inmortalidad. Yo llevo siglos aburrido.'),
  (54, 56, 'Bael''thor', 'Un pacto oscuro casi se le escapa de las manos a Bael''thor — lo ayudas antes de que el demonio invocado se vuelva contra él. "Cada pacto tiene un precio. El mío ya lo pagué. Espero que el tuyo, si algún día haces uno, sea más barato."', 'No pregunto qué le debes a la oscuridad. Solo espero que puedas pagarlo.'),
  (55, 57, 'Seraphina Lumis', 'Seres celestiales responden al llamado de Lumis con una devoción casi conmovedora — peleas junto a ellos sin que te traten como intruso. "Lo celestial no se invoca. Se le pide, con humildad. Tú ya entiendes esa diferencia."', 'Cada aliado celestial que llamo me recuerda cuánto me falta para merecerlos.'),
  (56, 58, 'Rhaska, Voz de la Manada', 'Bestias salvajes responden al llamado de Rhaska con una lealtad feroz — peleas a su lado y la manada te acepta sin dudar. "Las bestias no mienten como la gente. Por eso las prefiero."', 'La manada no me sigue por magia. Me sigue porque nunca les di razones para no hacerlo.'),
  (57, 59, 'Octavia, la de los Ocho Elementos', 'Octavia alterna entre los ocho elementos sin perder ni un segundo de ritmo — peleas a su lado y apenas logras seguirle el paso. "Dominar uno es un logro. Dominar los ocho es una carga que pocos eligen cargar."', 'Cada elemento que domino me cuesta un pedazo de mí dedicado solo a él. Elige bien cuáles priorizar.'),
  (58, 60, 'El Vacío que Habla', 'Algo que ya no parece del todo humano canaliza un poder cósmico casi incomprensible — peleas a su lado y sientes que algo antiguo te está evaluando. "Pocos llegan tan lejos. Menos todavía vuelven siendo reconocibles."', 'No preguntes qué soy ahora. Ni yo estoy seguro de la respuesta.'),
  (59, 61, 'Astraia, Eco de las Estrellas', 'Astraia canaliza un poder que parece venir de más allá del cielo mismo — peleas a su lado y por un instante ves algo que no deberías haber visto. "Pocos mortales tocan el poder de las estrellas sin quebrarse. Tú sigues de pie."', 'Casi nadie alcanza este poder. Los que lo hacen, rara vez siguen siendo los mismos.'),
  (60, 21, 'Kiro, Sombra Silenciosa', 'Kiro se mueve entre las sombras enfrentando a varios enemigos a la vez, casi sin ser visto — te sumas al ataque justo cuando el sigilo ya no alcanza. "Un ninja que necesita ayuda ya cometió un error. Gracias por no dejarme cometerlo del todo."', 'El silencio es mi arma más fuerte. Tú rompiste el mío, y no me molestó.'),
  (61, 22, 'Vex, Filo Rápido', 'Vex busca el golpe letal perfecto contra un objetivo esquivo — tu distracción le da la abertura que necesitaba. "Un golpe, una muerte. Tú me diste el momento exacto."', 'No cuento cuántos golpes letales llevo. Dejé de contar hace mucho.'),
  (62, 23, 'Fenna Dedos Ligeros', 'Fenna intenta robar algo de un enemigo mientras esquiva sus ataques — la cubres el tiempo suficiente para que complete el robo. "Robar en combate es el doble de riesgo por el doble de premio. Gracias por reducir el riesgo."', 'Doscientos robos después, todavía el mejor botín es la sorpresa en la cara de quien perdió algo.'),
  (63, 24, 'Sythe, Toque Letal', 'Sythe aplica veneno tras veneno mientras evita que el enemigo note el patrón — peleas a su lado disimulando el momento exacto. "El veneno perfecto es el que nadie nota hasta que ya es tarde. Tú ayudaste a que no lo notaran."', 'No envenené a nadie que no lo mereciera. Al menos, eso me digo para dormir tranquilo.'),
  (64, 25, 'Grix el Ingenioso', 'Una trampa de Grix casi se activa antes de tiempo, apuntando al enemigo equivocado — la desarmas y vuelves a tenderla a tiempo. "Cien trampas activadas y todavía cometo errores de cálculo. Gracias por corregir este."', 'La mejor trampa es la que nadie ve ni cuando ya cayó en ella.'),
  (65, 75, 'Kestrel, el Golpe Perfecto', 'Kestrel busca EL golpe, el que termina todo de una vez, contra un objetivo casi imposible — tu apoyo le da la ventana exacta. "El golpe perfecto no admite un segundo intento. Gracias por asegurarte de que no lo necesitara."', 'Perfeccioné un solo golpe toda mi vida. A veces me pregunto si valió la pena, y la respuesta siempre es sí.'),
  (66, 76, 'Draven, Cazador de Jefes', 'Draven enfrenta solo a algo mucho más grande que él, apostando todo a un instante — llegas justo para inclinar la balanza. "Cazar jefes es apostar tu vida en cada intento. Hoy la apuesta salió bien gracias a ti."', 'No cuento cuántos jefes caí. Cuento cuántas veces casi no vuelvo, y son demasiadas.'),
  (67, 77, 'Morwenna, Cinco Toxinas', 'Morwenna combina cinco venenos distintos en un solo combate, arriesgando confundirse ella misma — la ayudas a mantener el orden. "Cinco venenos a la vez es elegancia, no exceso. Tú entendiste la diferencia."', 'Cada toxina que domino tiene su propia personalidad. Aprende a respetarlas todas por igual.'),
  (68, 78, 'Shiro, Sombra Perfecta', 'Shiro ataca sin que nadie note siquiera que estuvo ahí — tú eres de las pocas personas que lo ve moverse, y no parece molestarle. "Si me viste, es porque te lo permití. No a cualquiera se lo permito."', 'El sigilo perfecto no busca aplausos. Busca que nadie sepa que hubo algo que aplaudir.'),
  (69, 79, 'Kurotsuki', 'Kurotsuki fusiona sigilo con magia oscura, casi perdiéndose en su propia sombra — lo ayudas a volver antes de que la sombra gane. "La oscuridad que uso a veces olvida devolverme. Gracias por recordarle que tenía que hacerlo."', 'No soy completamente yo cuando uso esta técnica. Espero que eso no te asuste.'),
  (70, 80, 'Rook, Leyenda Viva', 'Rook intenta un robo que ya es leyenda entre ladrones, arriesgando demasiado — tu ayuda convierte el intento en historia real. "Cada robo legendario empezó como una locura que casi no funciona. Gracias por la parte del ''casi''."', 'No robo por necesidad. Robo porque algunas cosas están mal guardadas y yo vine a corregir eso.'),
  (71, 81, 'Delphine Buscafortunas', 'Delphine casi activa una maldición antigua buscando un tesoro único — la sacas de la sala justo antes de que se cierre. "Cada tesoro único tiene su propio guardián. Hoy el guardián casi gana."', 'No busco oro. Busco cosas que nadie más pudo encontrar. El oro es solo una excusa.'),
  (72, 82, 'Cassian, Espada a Sueldo', 'Cassian pelea por contrato contra algo que claramente superó lo pactado — te sumas sin que te lo pidan, y él lo nota. "No peleo gratis, normalmente. Esto lo voy a recordar de todos modos."', 'El oro paga el riesgo. No paga la lealtad. Esa se gana aparte.'),
  (73, 83, 'Talia Sendasombría', 'Talia queda atrapada en un pasillo colapsado de una mazmorra peligrosa — la ayudas a abrirse paso de vuelta. "Cada mazmorra tiene un camino de salida. A veces hace falta ayuda para encontrarlo a tiempo."', 'Exploré ruinas que ni los mapas recuerdan. Todavía me sorprenden.'),
  (74, 84, 'Nadia, la que No Está', 'Nadia desaparece literalmente en medio del combate y reaparece detrás del enemigo — peleas a su lado sin saber nunca dónde va a estar. "Desaparecer no es magia. Es dejar de darle al otro una razón para mirarte."', 'Si me buscas, no me vas a encontrar. Si no me buscas, tampoco. Esa es la gracia.'),
  (75, 85, 'Otho Ojo Agudo', 'Otho detecta una trampa mortal un segundo antes de que se active sobre el grupo — reaccionas a tiempo gracias a su aviso. "Detectar el peligro antes de que exista es la única forma de sobrevivir a este oficio."', 'Nunca vi una trampa que no pudiera desactivar. Todavía no encontré la que me gane.'),
  (76, 86, 'Ryn, Filo de Tormenta', 'Ryn combina sigilo con destellos elementales impredecibles — peleas a su lado sin saber qué elemento va a usar después. "Combinar sigilo y magia elemental es un balance raro. Pocos lo intentan, menos lo logran."', 'El elemento que uso cambia con mi humor. Hoy, por suerte para ti, estaba de buen humor.'),
  (77, 87, 'Piroette', 'Piroette esquiva un ataque tras otro con una gracia casi imposible, hasta que el cansancio empieza a ganarle — la cubres el tiempo justo. "Nunca me golpean. Hoy casi. Gracias por el ''casi''."', 'La evasión perfecta no es no ser golpeado. Es asegurarte de que nunca sea la última vez que lo intentan.'),
  (78, 26, 'Hermana Marisol', 'Marisol cura heridas en medio del caos, agotando su maná justo cuando más se necesita — le das el respiro que necesita para seguir. "Curar en combate es correr contra el tiempo. Tú me diste tiempo extra."', 'Cada vida que salvo es una razón más para seguir despertándome cada día.'),
  (79, 27, 'Padre Osric', 'Osric invoca la naturaleza para contener una amenaza que crece más rápido de lo que puede controlar — lo ayudas a equilibrar la balanza. "La naturaleza da y quita en igual medida. Hoy te tocó a ti ayudarme a que diera un poco más."', 'No controlo la naturaleza. Negocio con ella, todos los días.'),
  (80, 28, 'Sir Ardonis', 'Ardonis sostiene un escudo mágico que empieza a resquebrajarse bajo el peso del ataque — refuerzas la defensa justo antes de que ceda. "La fe blindada todavía necesita compañía a veces. Gracias por ser esa compañía hoy."', 'Mi escudo no me protege a mí. Protege a los que están detrás. Nunca lo olvides.'),
  (81, 29, 'Madre Elyndra', 'Elyndra intenta curar a todo un grupo agotado con una sola oración masiva — la ayudas a sostener el hechizo hasta el final. "Curar a muchos a la vez cuesta más de lo que parece. Gracias por darme el tiempo para terminarlo."', 'Ninguna cura masiva reemplaza cuidar a cada uno como si fuera el único.'),
  (82, 30, 'Inquisidora Vesna', 'Vesna enfrenta algo profundamente corrupto que su propia magia apenas logra contener — peleas a su lado y la purga finalmente avanza. "Purificar la corrupción exige más fe de la que la mayoría tiene. Tú la tienes, aunque no lo sepas todavía."', 'No juzgo a quien cae en la oscuridad. Juzgo a quien elige quedarse ahí.'),
  (83, 88, 'Su Eminencia Tobar', 'Tobar canaliza curaciones masivas mientras dirige a un grupo entero fuera del peligro — te sumas a proteger su concentración. "Un obispo no pelea solo. Pelea guiando a otros a que no tengan que hacerlo tan seguido."', 'Cada curación masiva que lanzo es un rezo que decido compartir con todos a la vez.'),
  (84, 89, 'Meridia, la que No Deja Morir a Nadie', 'Meridia intenta un milagro imposible sobre alguien al borde de la muerte — tu ayuda inclina el milagro a su favor. "Nadie debería morir si yo estoy cerca. Hoy, gracias a ti, nadie murió."', 'No siempre puedo salvar a todos. Pero cada vez que puedo, elijo intentarlo de todas formas.'),
  (85, 90, 'Ancestro Verdehoja', 'Verdehoja canaliza la magia más antigua del bosque, casi perdiendo el control de su propio poder — lo ayudas a anclarlo. "La magia ancestral no se domina. Se le pide permiso, con humildad. Tú ya entiendes eso."', 'Antes de mí, otros cuidaron este poder. Después de mí, espero que alguien más lo haga.'),
  (86, 91, 'Faelan Guardián Verde', 'Faelan se interpone entre el peligro y un grupo de aliados heridos, usando toda la naturaleza a su alcance — peleas a su lado sosteniendo esa barrera. "Proteger no es una habilidad. Es una decisión que tomo cada vez que hace falta."', 'Cada aliado que protejo confía en que no voy a fallar. Todavía no fallé.'),
  (87, 92, 'Sir Baldric Fe Blindada', 'Baldric combina armadura pesada y fe inquebrantable contra algo que pone a prueba ambas — peleas a su lado y ninguna de las dos cede. "La fe blindada no es solo metal. Es convicción con forma de armadura. Tú ya la tienes."', 'Mi armadura pesa menos que la duda. Por eso elegí cargar con ella.'),
  (88, 93, 'Alteza Solmund', 'Solmund canaliza magia divina avanzada mientras contiene algo que amenaza con corromper todo a su alrededor — peleas a su lado y la luz se sostiene. "Pocos alcanzan la fe suprema sin perder de vista por qué empezaron. Tú no la perdiste."', 'El poder divino que uso no es mío. Es un préstamo que trato de merecer cada día.'),
  (89, 94, 'Su Severidad Kaltheus', 'Kaltheus enfrenta a una criatura temida por todas las cosas oscuras, apenas sosteniendo la purga — peleas a su lado y la criatura finalmente cae. "Las criaturas oscuras me temen por una buena razón. Hoy se las recordamos juntos."', 'No busco ser temido. Busco que lo oscuro tenga una razón para pensarlo dos veces.'),
  (90, 95, 'El Silente de la Montaña', 'Un monje sacerdote medita en medio del combate, alcanzando una calma que parece imposible bajo ataque — peleas protegiendo esa quietud. "La iluminación no se interrumpe con facilidad. Gracias por asegurarte de que nada la interrumpiera hoy."', 'No hablo de mi iluminación. Se nota, o no se nota. Las palabras no ayudan.'),
  (91, 96, 'Padre Ignathus', 'Ignathus enfrenta una posesión que se resiste con una violencia inusual — lo ayudas a completar el exorcismo antes de que se le escape. "Cada exorcismo es una negociación con algo que no quiere irse. Gracias por inclinar la negociación a mi favor."', 'Lo que expulso no desaparece. Solo deja de ser tu problema. A veces se vuelve el mío.'),
  (92, 97, 'Hermano Faelyn', 'Faelyn reparte bendiciones constantes a todo el que lo rodea, incluso en pleno peligro — te sumas y una de esas bendiciones te alcanza también. "Bendecir no cuesta nada, salvo el tiempo que a veces no tienes. Gracias por darme ese tiempo."', 'No elijo a quién bendecir. Elijo bendecir a todos y dejar que ellos decidan qué hacer con eso.'),
  (93, 98, 'Madre Yolanda', 'Yolanda prepara una poción sagrada en pleno combate, arriesgándose a que la interrumpan — la cubres hasta que termina. "Cada poción sagrada lleva su tiempo. Interrumpirla a mitad de camino la arruina. Gracias por el tiempo."', 'La alquimia sagrada no es magia instantánea. Es paciencia disfrazada de ciencia.'),
  (94, 99, 'Vesryn el Corrompido', 'Vesryn canaliza una fe oscura y corrompida que apenas logra controlar — peleas a su lado sin juzgarlo del todo. "Abracé la magia oscura sabiendo el precio. Todavía no me arrepiento, la mayoría de los días."', 'No pido que entiendas mi camino. Pido que no le des la espalda a quien lo eligió.'),
  (95, 100, 'Su Santidad Theodren', 'Theodren cura incontables heridas en una sola batalla, cada una con la misma devoción que la anterior — te sumas a proteger su resistencia. "Cada curación cuenta, aunque sean incontables. Gracias por asegurarte de que pudiera seguir contando."', 'No busco ser venerado. Busco que cada cura valga la pena, una por una.'),
  (96, 101, 'Nyssara, Ojos del Mañana', 'Nyssara predice cada movimiento enemigo un instante antes de que ocurra, pero la visión empieza a agotarla — la ayudas a sostenerla hasta el final del combate. "Ver el futuro en combate es agotador. Gracias por darme el tiempo para seguir viendo."', 'No siempre me gusta lo que veo venir. Pero prefiero saberlo a no saberlo.')
INSERT INTO items (id, code, name, item_type, slot, is_two_handed, rarity, class_id, required_level, is_craftable, obtain_method, description, buy_price) VALUES
  (1, 'ESPADA_DE_HIERRO', 'Espada de Hierro', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 1, 1, FALSE, 'Inicial, Tienda, Combate', 'Primera espada de un guerrero novato.', NULL),
  (2, 'GRAN_ESPADA_DE_HIERRO', 'Gran Espada de Hierro', 'EQUIPMENT', 'WEAPON', TRUE, 'POCO_COMUN', 1, 5, FALSE, 'Tienda, Quests, Combate', 'Espada pesada de dos manos. No se puede usar escudo junto a ella.', NULL),
  (3, 'ESCUDO_DE_TITAN', 'Escudo de Titán', 'EQUIPMENT', 'OFFHAND', FALSE, 'RARO', 1, 20, FALSE, 'Quests difíciles, Tienda', 'Escudo forjado para resistir los golpes más brutales.', NULL),
  (4, 'ESPADA_DEL_DRAGON', 'Espada del Dragón', 'EQUIPMENT', 'WEAPON', FALSE, 'EPICO', 1, 40, FALSE, 'Bosses especiales, Crafteo', 'Forjada con escamas de dragón, especialmente letal contra estas bestias.', NULL),
  (5, 'EXCALIBUR', 'Excálibur', 'EQUIPMENT', 'WEAPON', FALSE, 'LEGENDARIO', 1, 70, FALSE, 'Boss Final único', 'La espada legendaria. Otorga la habilidad especial "Corte Divino".', NULL),
  (6, 'BACULO_DE_APRENDIZ', 'Báculo de Aprendiz', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 2, 1, FALSE, 'Inicial, Tienda, Combate', 'Báculo simple para los primeros hechizos.', NULL),
  (7, 'ORBE_DE_FUEGO', 'Orbe de Fuego', 'EQUIPMENT', 'OFFHAND', FALSE, 'POCO_COMUN', 2, 10, FALSE, 'Tienda, Combate, Quests', 'Orbe que arde con fuego interno, potencia la magia de fuego.', NULL),
  (8, 'BACULO_ANTIGUO', 'Báculo Antiguo', 'EQUIPMENT', 'WEAPON', FALSE, 'RARO', 2, 25, FALSE, 'Quests, Tienda, Dungeons', 'Báculo de origen olvidado que regenera maná por sí solo.', NULL),
  (9, 'CRISTAL_SUPREMO', 'Cristal Supremo', 'EQUIPMENT', 'OFFHAND', FALSE, 'EPICO', 2, 50, FALSE, 'Bosses especiales, Crafteo', 'Cristal de poder elemental concentrado.', NULL),
  (10, 'BACULO_DE_LA_ETERNIDAD', 'Báculo de la Eternidad', 'EQUIPMENT', 'WEAPON', FALSE, 'LEGENDARIO', 2, 75, FALSE, 'Boss Final único', 'El báculo definitivo. Otorga la habilidad especial "Tormenta Cósmica".', NULL),
  (11, 'ARCO_DE_MADERA', 'Arco de Madera', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 3, 1, FALSE, 'Inicial, Tienda, Combate', 'Arco básico tallado en madera.', NULL),
  (12, 'ARCO_DE_PRECISION', 'Arco de Precisión', 'EQUIPMENT', 'WEAPON', FALSE, 'POCO_COMUN', 3, 8, FALSE, 'Tienda, Quests, Combate', 'Arco balanceado para disparos certeros.', NULL),
  (13, 'ARCO_DEL_CAZADOR', 'Arco del Cazador', 'EQUIPMENT', 'WEAPON', FALSE, 'RARO', 3, 30, FALSE, 'Quests de caza, Tienda', 'Arco preferido por cazadores expertos, especialmente letal contra bestias.', NULL),
  (14, 'ARCO_DE_LOS_DIOSES', 'Arco de los Dioses', 'EQUIPMENT', 'WEAPON', FALSE, 'EPICO', 3, 55, FALSE, 'Bosses especiales, Crafteo', 'Arco de origen divino cuyas flechas atraviesan a los enemigos.', NULL),
  (15, 'ARCO_DE_ORION', 'Arco de Orión', 'EQUIPMENT', 'WEAPON', FALSE, 'LEGENDARIO', 3, 80, FALSE, 'Boss Final único', 'El arco definitivo. Otorga la habilidad especial "Lluvia Infinita".', NULL),
  (16, 'DAGA_DE_HIERRO', 'Daga de Hierro', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 4, 1, FALSE, 'Inicial, Tienda, Combate', 'Daga ligera ideal para golpes rápidos.', NULL),
  (17, 'DAGA_DE_PRECISION', 'Daga de Precisión', 'EQUIPMENT', 'WEAPON', FALSE, 'POCO_COMUN', 4, 10, FALSE, 'Tienda, Quests, Combate', 'Daga afilada con balance perfecto.', NULL),
