  (1046, 'MORWENNA_DAGA_DE_LAS', 'Daga de las Cinco Toxinas', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 77, 35, FALSE, 'Tienda de Morwenna, Cinco Toxinas (gremio)', 'Cinco venenos a la vez es elegancia, no exceso, para Morwenna.', NULL),
  (1047, 'MORWENNA_FRASCO_DE_LAS', 'Frasco de las Cinco Toxinas', 'MATERIAL', NULL, FALSE, 'COMUN', NULL, NULL, FALSE, 'Tienda de Morwenna, Cinco Toxinas (gremio)', 'Cada toxina que domina Morwenna tiene su propia personalidad.', NULL),
