  (1051, 'KUROTSUKI_SOMBRA_FUNDIDA_DE', 'Sombra Fundida de Kurotsuki', 'MATERIAL', NULL, FALSE, 'COMUN', NULL, NULL, FALSE, 'Tienda de Kurotsuki (gremio)', 'Kurotsuki no es completamente él mismo cuando usa esta técnica.', NULL),
  (1052, 'ROOK_DAGA_DE_LA', 'Daga de la Leyenda Viva', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 80, 35, FALSE, 'Tienda de Rook, Leyenda Viva (gremio)', 'Cada robo legendario de Rook empezó como una locura que casi no funciona.', NULL),
  (1053, 'ROOK_BOTIN_LEGENDARIO_DE', 'Botín Legendario de Rook', 'MATERIAL', NULL, FALSE, 'COMUN', NULL, NULL, FALSE, 'Tienda de Rook, Leyenda Viva (gremio)', 'Rook no roba por necesidad. Roba porque algunas cosas están mal guardadas.', NULL),
  (1054, 'DELPHINE_BUSCAFORTUNAS_DAGA_DE_LA', 'Daga de la Buscafortunas', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 81, 40, FALSE, 'Tienda de Delphine Buscafortunas (gremio)', 'Cada tesoro único tiene su propio guardián. Delphine casi pierde contra el suyo.', NULL),
