  (1056, 'CASSIAN_ESPADA_A_SUELDO', 'Espada a Sueldo de Cassian', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 82, 30, FALSE, 'Tienda de Cassian, Espada a Sueldo (gremio)', 'Cassian no pelea gratis, normalmente. Esto lo va a recordar de todos modos.', NULL),
  (1057, 'CASSIAN_CONTRATO_DE_CASSIAN', 'Contrato de Cassian', 'MATERIAL', NULL, FALSE, 'COMUN', NULL, NULL, FALSE, 'Tienda de Cassian, Espada a Sueldo (gremio)', 'El oro paga el riesgo. No paga la lealtad, que Cassian gana aparte.', NULL),
  (1058, 'TALIA_SENDASOMBRIA_DAGA_DE_SENDASOMBRIA', 'Daga de Sendasombría', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 83, 30, FALSE, 'Tienda de Talia Sendasombría (gremio)', 'Cada mazmorra tiene un camino de salida, y Talia siempre lo encuentra.', NULL),
