  (1060, 'NADIA_DAGA_DE_LA', 'Daga de la que No Está', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 84, 35, FALSE, 'Tienda de Nadia, la que No Está (gremio)', 'Desaparecer no es magia para Nadia. Es dejar de darle al otro una razón para mirarla.', NULL),
  (1061, 'NADIA_RASTRO_DE_NADIA', 'Rastro de Nadia', 'MATERIAL', NULL, FALSE, 'COMUN', NULL, NULL, FALSE, 'Tienda de Nadia, la que No Está (gremio)', 'Si la buscás, no la vas a encontrar. Si no la buscás, tampoco.', NULL),
