  (1065, 'RYN_CHISPA_DE_RYN', 'Chispa de Ryn', 'MATERIAL', NULL, FALSE, 'COMUN', NULL, NULL, FALSE, 'Tienda de Ryn, Filo de Tormenta (gremio)', 'El elemento que usa Ryn cambia con su humor.', NULL),
  (1066, 'PIROETTE_DAGA_DE_PIROETTE', 'Daga de Piroette', 'EQUIPMENT', 'WEAPON', FALSE, 'COMUN', 87, 25, FALSE, 'Tienda de Piroette (gremio)', 'Piroette nunca es golpeada. Hoy casi.', NULL),
