INSERT INTO pets (id, code, name, rarity, element_id, description) VALUES
  (1, 'LOBO_CACHORRO', 'Lobo Cachorro', 'COMUN', NULL, 'Un lobo joven lleno de energía. Aumenta el ATK del portador.'),
  (2, 'RATON_AGIL', 'Ratón Ágil', 'COMUN', NULL, 'Un ratón veloz que mejora la velocidad en combate.'),
  (3, 'ZORRO_ASTUTO', 'Zorro Astuto', 'POCO_COMUN', NULL, 'Un zorro ladino que ayuda a encontrar más oro.'),
  (4, 'ARANA_CRISTAL', 'Araña de Cristal', 'POCO_COMUN', NULL, 'Una araña translúcida que enseña a esquivar golpes.'),
  (5, 'TORTUGA_ESCUDO', 'Tortuga Escudo', 'POCO_COMUN', NULL, 'Una tortuga robusta que fortalece la defensa.'),
  (6, 'SALAMANDRA_FUEGO', 'Salamandra de Fuego', 'RARO', 1, 'Una salamandra ígnea que potencia el daño elemental.'),
  (7, 'IMP_OSCURO', 'Imp Oscuro', 'RARO', 8, 'Un imp travieso que ayuda a ganar más experiencia.'),
  (8, 'GOLEM_TIERRA', 'Gólem de Tierra', 'RARO', 5, 'Un gólem rocoso que reduce el daño recibido.'),
  (9, 'DRAGON_MENOR', 'Dragón Menor', 'EPICO', NULL, 'Un dragón joven que amplifica el daño físico.'),
  (10, 'FAMILIAR_ARCANO', 'Familiar Arcano', 'EPICO', 7, 'Un ser de luz que potencia la magia y el maná.'),
  (11, 'LOBO_COSMICO', 'Lobo Cósmico', 'EPICO', 9, 'Un lobo estelar que mejora la suerte y el botín.'),
  (12, 'FENIX', 'Fénix', 'LEGENDARIO', 1, 'Ave mítica de fuego. Revive al portador una vez por combate.'),
  (13, 'DRAGON_PRIMORDIAL', 'Dragón Primordial', 'LEGENDARIO', NULL, 'El más poderoso de los dragones. Amplifica todo daño masivamente.')
INSERT INTO quests (id, code, name, quest_type, zone_id, chain_position, chain_total, is_boss_quest, requires_quest_id, min_level, max_level, difficulty_stars, min_rank_code, npc_name, location_name, is_repeatable, repeat_cooldown_hours, reputation_reward, gold_reward, xp_reward, hidden_unlock_text, description, required_class_id) VALUES
  (1, 'PRADERA_Q1_LOBO_DEL_BOSQUE', 'El Lobo del Bosque', 'PRINCIPAL', 1, 1, 3, FALSE, NULL, 1, 15, 1, NULL, 'Guardabosque Local', 'Entrada Bosque Pradera', FALSE, NULL, 100, 300, 200, NULL, 'Los lobos atacan a los aldeanos. Elimina 5 Lobos de Pradera como demostración de tu valor.', NULL),
  (2, 'PRADERA_Q2_BANDIDO_PRADERA', 'El Bandido de la Pradera', 'PRINCIPAL', 1, 2, 3, FALSE, 1, 1, 15, 2, NULL, 'Comerciante de la Aldea', 'Centro de la Aldea', FALSE, NULL, 150, 400, 250, NULL, 'Los bandidos saquean los suministros del comerciante. Derrota a 3 Bandidos Corruptos.', NULL),
  (3, 'PRADERA_Q3_TITAN_PRADERA', 'El Titán de la Pradera', 'PRINCIPAL', 1, 3, 3, TRUE, 2, 14, 15, 4, NULL, 'Anciano Sabio', 'Corazón de la Pradera', FALSE, NULL, 300, 1200, 800, NULL, 'El Titán de la Pradera ha sido avistado. Derrótalo para demostrar que eres digno de ser un aventurero.', NULL),
  (4, 'PRADERA_DAILY_EXTERMINIO', 'Exterminio Diario: Alimañas de la Pradera', 'DIARIA', 1, NULL, NULL, FALSE, NULL, 8, 15, 1, NULL, 'Guardabosque Local', 'Entrada Bosque Pradera', TRUE, 6, 30, 150, 100, NULL, 'Elimina 10 enemigos comunes de la Pradera Dorada.', NULL),
  (5, 'PRADERA_DAILY_PLAGA_ROEDORES', 'Plaga de Roedores y Arácnidos', 'DIARIA', 1, NULL, NULL, FALSE, NULL, 1, 15, 2, NULL, 'Guardabosque Local', 'Entrada Bosque Pradera', TRUE, 6, 45, 500, 200, NULL, 'Elimina enemigos de la zona: Ratas de Alcantarilla, Arañas Venenosas, Goblins Saqueadores.', NULL),
