INSERT INTO achievements (id, code, name, description, condition_type, quest_id, threshold, bonus_type, bonus_category, bonus_stat, bonus_percent) VALUES
  (1, 'ACH_EXTERMINADOR_RATAS', 'Exterminador de Ratas', 'Completaste 100 veces la caza de ratas. Los túneles te temen.', 'QUEST_COMPLETIONS', 50, 100, 'DAMAGE_VS_CATEGORY', 'BESTIA', NULL, 5),
  (2, 'ACH_CAZADOR_ARANAS', 'Cazador de Arañas', 'Las telarañas ya no son obstáculo para ti.', 'QUEST_COMPLETIONS', 51, 100, 'DAMAGE_VS_CATEGORY', 'INSECTOIDE', NULL, 5),
  (3, 'ACH_VERDUGO_GOBLIN', 'Verdugo Goblin', 'Los goblins susurran tu nombre con miedo.', 'QUEST_COMPLETIONS', 52, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (4, 'ACH_ASESINO_LOBOS', 'Asesino de Lobos', 'Has cazado tantos lobos que la manada te considera su depredador natural.', 'QUEST_COMPLETIONS', 53, 100, 'DAMAGE_VS_CATEGORY', 'BESTIA', NULL, 10),
  (5, 'ACH_SENOR_PRADERA', 'Señor de la Pradera', 'Los animales de la pradera reconocen en ti a su verdadero depredador.', 'QUEST_COMPLETIONS', 6, 100, 'DAMAGE_VS_CATEGORY', 'BESTIA', NULL, 5),
  (6, 'ACH_MATADOR_ORCOS', 'Matador de Orcos', 'Los orcos de la montaña prefieren evitarte.', 'QUEST_COMPLETIONS', 57, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (7, 'ACH_CAZADOR_ESPECTROS', 'Cazador de Espectros', 'Tu voluntad es más fuerte que cualquier espectro.', 'QUEST_COMPLETIONS', 58, 100, 'DAMAGE_VS_CATEGORY', 'ESPECTRO', NULL, 5),
  (8, 'ACH_ROMPE_TROLLS', 'Rompe-Trolls', 'Has derribado más trolls que ningún guerrero conocido.', 'QUEST_COMPLETIONS', 59, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (9, 'ACH_PURIFICADOR_MINA', 'Purificador de la Mina', 'La corrupción no puede esconderse de ti.', 'QUEST_COMPLETIONS', 60, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (10, 'ACH_CAZADOR_ESCAMAS', 'Cazador de Escamas', 'Las criaturas con escamas tiemblan ante tu presencia.', 'QUEST_COMPLETIONS', 65, 100, 'DAMAGE_VS_CATEGORY', 'BESTIA', NULL, 5),
  (11, 'ACH_EXORCISTA_MAGMA', 'Exorcista de Magma', 'Has enviado al inframundo más demonios de los que puedes contar.', 'QUEST_COMPLETIONS', 66, 100, 'DAMAGE_VS_CATEGORY', 'DEMONIO', NULL, 10),
  (12, 'ACH_VERDUGO_VOLCAN', 'Verdugo del Volcán', 'Los bandidos del volcán pagan el precio de cruzarte.', 'QUEST_COMPLETIONS', 67, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (13, 'ACH_CONTRA_EL_CANTO', 'Contra el Canto', 'Eres inmune al encanto de las sirenas. Tus golpes también.', 'QUEST_COMPLETIONS', 73, 100, 'DAMAGE_VS_CATEGORY', 'ACUATICO', NULL, 5),
  (14, 'ACH_PESCADOR_LETAL', 'Pescador Letal', 'Cada criatura acuática que encuentras se convierte en tu presa.', 'QUEST_COMPLETIONS', 74, 100, 'DAMAGE_VS_CATEGORY', 'ACUATICO', NULL, 5),
  (15, 'ACH_ROMPE_QUELAS', 'Rompe-Quelas', 'Has roto más pinzas de cangrejo que un cocinero de palacio.', 'QUEST_COMPLETIONS', 75, 100, 'DAMAGE_VS_CATEGORY', 'ACUATICO', NULL, 5),
  (16, 'ACH_DESCANSA_EN_PAZ', 'Descansa en Paz', 'Los muertos del mar ya no te dan miedo. Tú les das miedo a ellos.', 'QUEST_COMPLETIONS', 76, 100, 'DAMAGE_VS_CATEGORY', 'MUERTO_VIVIENTE', NULL, 5),
  (17, 'ACH_SENOR_HIELO_ETERNO', 'Señor del Hielo Eterno', 'Los lobos del hielo reconocen a su depredador supremo.', 'QUEST_COMPLETIONS', 81, 100, 'DAMAGE_VS_CATEGORY', 'BESTIA', NULL, 10),
  (18, 'ACH_GIGANTE_CAZADOR', 'Gigante-Cazador', 'Ningún gigante de nieve puede intimidarte ya.', 'QUEST_COMPLETIONS', 82, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (19, 'ACH_DOMADOR_COLMILLOS', 'Domador de Colmillos', 'Los jabalíes helados huyen cuando detectan tu rastro.', 'QUEST_COMPLETIONS', 84, 100, 'DAMAGE_VS_CATEGORY', 'BESTIA', NULL, 5),
  (20, 'ACH_CAZAFANTASMAS', 'Cazafantasmas', 'Eres el terror de los espíritus encadenados.', 'QUEST_COMPLETIONS', 90, 100, 'DAMAGE_VS_CATEGORY', 'ESPECTRO', NULL, 10),
  (21, 'ACH_PURIFICADOR_ALMAS', 'Purificador de Almas', 'Has purificado más muertos vivientes que un sacerdote de alto rango.', 'QUEST_COMPLETIONS', 91, 100, 'DAMAGE_VS_CATEGORY', 'MUERTO_VIVIENTE', NULL, 10),
  (22, 'ACH_ETERNO_VERDUGO', 'El Eterno Verdugo', 'Los cadáveres reanimados no tienen descanso cuando estás cerca.', 'QUEST_COMPLETIONS', 92, 100, 'DAMAGE_VS_CATEGORY', 'MUERTO_VIVIENTE', NULL, 5),
  (23, 'ACH_ROMPEMALDICIONES', 'Rompemaldiciones', 'Has destruido tantos sacerdotes malditos que la oscuridad te teme.', 'QUEST_COMPLETIONS', 89, 100, 'DAMAGE_VS_CATEGORY', 'HUMANOIDE', NULL, 5),
  (24, 'ACH_GUARDIAN_DE_GUARDIANES', 'Guardián de Guardianes', 'Has destruido más guardianes elementales que cualquier explorador de las ruinas.', 'QUEST_COMPLETIONS', 47, 100, 'DAMAGE_VS_CATEGORY', 'ELEMENTAL', NULL, 10)
